package checkpoint

import (
	"fmt"
	"path/filepath"
	"sort"
	"strings"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/filemode"
	"github.com/go-git/go-git/v5/plumbing/object"
)

// TreeChange represents a single file change within a tree.
// Use a nil Entry to indicate deletion.
type TreeChange struct {
	// Path is the full path within the tree (e.g., "src/pkg/handler.go").
	Path string
	// Entry is the new tree entry. Nil means delete the file at Path.
	Entry *object.TreeEntry
}

// MergeMode controls how entries at the leaf directory are handled.
type MergeMode int

const (
	// ReplaceAll replaces the entire leaf directory contents with the new entries.
	ReplaceAll MergeMode = iota
	// MergeKeepExisting merges new entries into the existing leaf directory,
	// keeping existing entries that are not overwritten (unless in DeleteNames).
	MergeKeepExisting
)

// UpdateSubtreeOptions configures the behavior of UpdateSubtree.
type UpdateSubtreeOptions struct {
	// MergeMode controls how entries at the leaf directory are handled.
	MergeMode MergeMode
	// DeleteNames lists entry names (at the leaf directory level) to delete.
	// Only applicable when MergeMode is MergeKeepExisting.
	DeleteNames []string
}

// UpdateSubtree replaces or creates a subtree at the given path within an existing tree.
// It walks the tree path, replacing only the entries along the modified path.
// All sibling entries at each level retain their original hashes (no re-reading or re-building).
//
// pathSegments is the directory path split into segments (e.g., ["a3", "b2c4d5e6f7", "0"]).
// newEntries are the files/dirs to place at the leaf directory.
//
// Returns the new root tree hash.
func UpdateSubtree(
	repo *git.Repository,
	rootTreeHash plumbing.Hash,
	pathSegments []string,
	newEntries []object.TreeEntry,
	opts UpdateSubtreeOptions,
) (plumbing.Hash, error) {
	if len(pathSegments) == 0 {
		return buildLeafTree(repo, rootTreeHash, newEntries, opts)
	}

	// Read the current tree at this level
	var currentEntries []object.TreeEntry
	if rootTreeHash != plumbing.ZeroHash {
		tree, err := repo.TreeObject(rootTreeHash)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to read tree: %w", err)
		}
		currentEntries = tree.Entries
	}

	targetDir := pathSegments[0]
	remainingPath := pathSegments[1:]

	// Find the existing subtree entry for targetDir
	var existingSubtreeHash plumbing.Hash
	found := false
	for _, entry := range currentEntries {
		if entry.Name == targetDir && entry.Mode == filemode.Dir {
			existingSubtreeHash = entry.Hash
			found = true
			break
		}
	}

	// Recurse into the subtree
	newSubtreeHash, err := UpdateSubtree(repo, existingSubtreeHash, remainingPath, newEntries, opts)
	if err != nil {
		return plumbing.ZeroHash, err
	}

	// Build a new tree at this level with the updated subtree entry
	updatedEntries := make([]object.TreeEntry, 0, len(currentEntries)+1)
	replaced := false
	for _, entry := range currentEntries {
		if entry.Name == targetDir {
			updatedEntries = append(updatedEntries, object.TreeEntry{
				Name: targetDir,
				Mode: filemode.Dir,
				Hash: newSubtreeHash,
			})
			replaced = true
		} else {
			updatedEntries = append(updatedEntries, entry)
		}
	}
	if !found && !replaced {
		updatedEntries = append(updatedEntries, object.TreeEntry{
			Name: targetDir,
			Mode: filemode.Dir,
			Hash: newSubtreeHash,
		})
	}

	sortTreeEntries(updatedEntries)
	return storeTree(repo, updatedEntries)
}

// buildLeafTree builds the tree at the leaf of the path.
func buildLeafTree(repo *git.Repository, existingTreeHash plumbing.Hash, newEntries []object.TreeEntry, opts UpdateSubtreeOptions) (plumbing.Hash, error) {
	if opts.MergeMode == ReplaceAll || existingTreeHash == plumbing.ZeroHash {
		sortTreeEntries(newEntries)
		return storeTree(repo, newEntries)
	}

	// MergeKeepExisting: read existing tree, merge
	existingTree, err := repo.TreeObject(existingTreeHash)
	if err != nil {
		sortTreeEntries(newEntries)
		return storeTree(repo, newEntries)
	}

	// Build lookup of new entries by name
	newByName := make(map[string]object.TreeEntry, len(newEntries))
	for _, e := range newEntries {
		newByName[e.Name] = e
	}

	// Build delete set
	deleteSet := make(map[string]bool, len(opts.DeleteNames))
	for _, name := range opts.DeleteNames {
		deleteSet[name] = true
	}

	// Merge: keep existing unless overwritten or deleted
	merged := make([]object.TreeEntry, 0, len(existingTree.Entries)+len(newEntries))
	for _, existing := range existingTree.Entries {
		if deleteSet[existing.Name] {
			continue
		}
		if replacement, ok := newByName[existing.Name]; ok {
			merged = append(merged, replacement)
			delete(newByName, existing.Name)
		} else {
			merged = append(merged, existing)
		}
	}
	// Add remaining new entries
	for _, e := range newEntries {
		if _, stillNew := newByName[e.Name]; stillNew {
			merged = append(merged, e)
		}
	}

	sortTreeEntries(merged)
	return storeTree(repo, merged)
}

// storeTree creates a git tree object from entries and stores it in the repo.
func storeTree(repo *git.Repository, entries []object.TreeEntry) (plumbing.Hash, error) {
	tree := &object.Tree{Entries: entries}
	obj := repo.Storer.NewEncodedObject()
	if err := tree.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
	}
	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
	}
	return hash, nil
}

// ApplyTreeChanges applies multiple file-level changes to a tree efficiently.
// Changes are grouped by directory and applied in a single recursive pass.
// Unchanged subdirectories retain their hashes.
func ApplyTreeChanges(
	repo *git.Repository,
	rootTreeHash plumbing.Hash,
	changes []TreeChange,
) (plumbing.Hash, error) {
	if len(changes) == 0 {
		return rootTreeHash, nil
	}

	// Read the current root tree
	var currentEntries []object.TreeEntry
	if rootTreeHash != plumbing.ZeroHash {
		tree, err := repo.TreeObject(rootTreeHash)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to read tree: %w", err)
		}
		currentEntries = make([]object.TreeEntry, len(tree.Entries))
		copy(currentEntries, tree.Entries)
	}

	// Group changes by first path segment
	type dirChanges struct {
		subChanges []TreeChange // Changes within this subdirectory (paths stripped of first segment)
		fileChange *TreeChange  // Direct file change at this level
	}
	grouped := make(map[string]*dirChanges)

	for i := range changes {
		c := changes[i]
		dir, rest := splitFirstSegment(c.Path)
		if grouped[dir] == nil {
			grouped[dir] = &dirChanges{}
		}
		if rest == "" {
			// File at this level
			cc := c
			grouped[dir].fileChange = &cc
		} else {
			// In a subdirectory
			grouped[dir].subChanges = append(grouped[dir].subChanges, TreeChange{
				Path:  rest,
				Entry: c.Entry,
			})
		}
	}

	// Build entry map for quick lookup
	entryMap := make(map[string]object.TreeEntry, len(currentEntries))
	entryOrder := make([]string, 0, len(currentEntries))
	for _, e := range currentEntries {
		entryMap[e.Name] = e
		entryOrder = append(entryOrder, e.Name)
	}

	// Process each group
	for name, dc := range grouped {
		if dc.fileChange != nil {
			if dc.fileChange.Entry == nil {
				// Delete
				delete(entryMap, name)
			} else {
				// Add/update file
				if _, exists := entryMap[name]; !exists {
					entryOrder = append(entryOrder, name)
				}
				entryMap[name] = object.TreeEntry{
					Name: name,
					Mode: dc.fileChange.Entry.Mode,
					Hash: dc.fileChange.Entry.Hash,
				}
			}
		}
		if len(dc.subChanges) > 0 {
			// Recurse into subdirectory
			existingHash := plumbing.ZeroHash
			if existing, ok := entryMap[name]; ok && existing.Mode == filemode.Dir {
				existingHash = existing.Hash
			}
			newSubHash, err := ApplyTreeChanges(repo, existingHash, dc.subChanges)
			if err != nil {
				return plumbing.ZeroHash, fmt.Errorf("failed to apply changes in %s: %w", name, err)
			}
			if _, exists := entryMap[name]; !exists {
				entryOrder = append(entryOrder, name)
			}
			entryMap[name] = object.TreeEntry{
				Name: name,
				Mode: filemode.Dir,
				Hash: newSubHash,
			}
		}
	}

	// Convert back to slice
	result := make([]object.TreeEntry, 0, len(entryMap))
	for _, e := range entryMap {
		result = append(result, e)
	}
	sortTreeEntries(result)
	return storeTree(repo, result)
}

// splitFirstSegment splits a path into its first segment and the rest.
// e.g., "a/b/c" -> ("a", "b/c"), "file.txt" -> ("file.txt", "")
func splitFirstSegment(path string) (first, rest string) {
	// Use filepath-aware splitting to handle both / and platform separators
	parts := strings.SplitN(filepath.ToSlash(path), "/", 2)
	if len(parts) == 1 {
		return parts[0], ""
	}
	return parts[0], parts[1]
}

// getSessionsBranchRef returns the sessions branch reference hash and root tree hash
// without flattening the tree. This is the optimized replacement for getSessionsBranchEntries.
func (s *GitStore) getSessionsBranchRef() (plumbing.Hash, plumbing.Hash, error) {
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get sessions branch reference: %w", err)
	}

	parentCommit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit object: %w", err)
	}

	return ref.Hash(), parentCommit.TreeHash, nil
}

// readCheckpointTree reads the tree at a checkpoint's shard path (e.g., "a3/b2c4d5e6f7").
// Returns nil if the path doesn't exist (new checkpoint).
func (s *GitStore) readCheckpointTree(rootTreeHash plumbing.Hash, checkpointPath string) (*object.Tree, error) {
	if rootTreeHash == plumbing.ZeroHash {
		return nil, nil //nolint:nilnil // Empty tree means new checkpoint
	}

	rootTree, err := s.repo.TreeObject(rootTreeHash)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Can't read root tree, treat as new
	}

	tree, err := rootTree.Tree(checkpointPath)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Path doesn't exist, treat as new
	}
	return tree, nil
}

// findSessionIndexFromTree finds the session index by reading session metadata
// directly from the checkpoint tree. Returns the index to use for this session.
func (s *GitStore) findSessionIndexFromTree(checkpointTree *object.Tree, existingSummary *CheckpointSummary, sessionID string) int {
	if existingSummary == nil || checkpointTree == nil {
		return 0
	}

	for i := range len(existingSummary.Sessions) {
		sessionDir := fmt.Sprintf("%d", i)
		sessionTree, err := checkpointTree.Tree(sessionDir)
		if err != nil {
			continue
		}
		metaFile, err := sessionTree.File(paths.MetadataFileName)
		if err != nil {
			continue
		}
		content, err := metaFile.Contents()
		if err != nil {
			continue
		}
		var meta CommittedMetadata
		if jsonErr := json.Unmarshal([]byte(content), &meta); jsonErr == nil {
			if meta.SessionID == sessionID {
				return i
			}
		}
	}
	return len(existingSummary.Sessions)
}

// reaggregateFromTree reads all session metadata from the checkpoint tree and
// reaggregates CheckpointsCount, FilesTouched, and TokenUsage.
func (s *GitStore) reaggregateFromTree(checkpointTree *object.Tree, sessionCount int) (int, []string, *agent.TokenUsage, error) {
	var totalCount int
	var allFiles []string
	var totalTokens *agent.TokenUsage

	for i := range sessionCount {
		sessionDir := fmt.Sprintf("%d", i)
		sessionTree, err := checkpointTree.Tree(sessionDir)
		if err != nil {
			return 0, nil, nil, fmt.Errorf("session %d tree not found", i)
		}
		metaFile, err := sessionTree.File(paths.MetadataFileName)
		if err != nil {
			return 0, nil, nil, fmt.Errorf("session %d metadata not found", i)
		}
		content, err := metaFile.Contents()
		if err != nil {
			return 0, nil, nil, fmt.Errorf("failed to read session %d metadata: %w", i, err)
		}
		var meta CommittedMetadata
		if jsonErr := json.Unmarshal([]byte(content), &meta); jsonErr != nil {
			return 0, nil, nil, fmt.Errorf("failed to parse session %d metadata: %w", i, jsonErr)
		}
		totalCount += meta.CheckpointsCount
		allFiles = mergeFilesTouched(allFiles, meta.FilesTouched)
		totalTokens = aggregateTokenUsage(totalTokens, meta.TokenUsage)
	}

	return totalCount, allFiles, totalTokens, nil
}

// readSummaryFromTree reads the CheckpointSummary from a checkpoint tree.
func (s *GitStore) readSummaryFromTree(checkpointTree *object.Tree) (*CheckpointSummary, error) {
	if checkpointTree == nil {
		return nil, nil //nolint:nilnil // No tree means no summary
	}
	metaFile, err := checkpointTree.File(paths.MetadataFileName)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // No metadata file
	}
	content, err := metaFile.Contents()
	if err != nil {
		return nil, fmt.Errorf("failed to read metadata.json: %w", err)
	}
	var summary CheckpointSummary
	if jsonErr := json.Unmarshal([]byte(content), &summary); jsonErr != nil {
		return nil, fmt.Errorf("failed to parse metadata.json: %w", jsonErr)
	}
	return &summary, nil
}

// buildSessionSubtreeEntries builds the tree entries for a session subdirectory.
// Returns entries that should be placed inside the session's numbered directory.
func (s *GitStore) buildSessionSubtreeEntries(opts WriteCommittedOptions) ([]object.TreeEntry, SessionFilePaths, error) {
	var entries []object.TreeEntry
	filePaths := SessionFilePaths{}

	// Write transcript
	transcriptEntries, err := s.buildTranscriptEntries(opts)
	if err != nil {
		return nil, filePaths, err
	}
	entries = append(entries, transcriptEntries...)
	if len(transcriptEntries) > 0 {
		filePaths.Transcript = "/" + paths.TranscriptFileName
		filePaths.ContentHash = "/" + paths.ContentHashFileName
	}

	// Write prompts
	if len(opts.Prompts) > 0 {
		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
		if err != nil {
			return nil, filePaths, err
		}
		entries = append(entries, object.TreeEntry{
			Name: paths.PromptFileName,
			Mode: filemode.Regular,
			Hash: blobHash,
		})
		filePaths.Prompt = "/" + paths.PromptFileName
	}

	// Write context
	if len(opts.Context) > 0 {
		blobHash, err := CreateBlobFromContent(s.repo, redact.Bytes(opts.Context))
		if err != nil {
			return nil, filePaths, err
		}
		entries = append(entries, object.TreeEntry{
			Name: paths.ContextFileName,
			Mode: filemode.Regular,
			Hash: blobHash,
		})
		filePaths.Context = "/" + paths.ContextFileName
	}

	// Write session metadata
	sessionMetadata := CommittedMetadata{
		CheckpointID:                opts.CheckpointID,
		SessionID:                   opts.SessionID,
		Strategy:                    opts.Strategy,
		CreatedAt:                   time.Now().UTC(),
		Branch:                      opts.Branch,
		CheckpointsCount:            opts.CheckpointsCount,
		FilesTouched:                opts.FilesTouched,
		Agent:                       opts.Agent,
		TurnID:                      opts.TurnID,
		IsTask:                      opts.IsTask,
		ToolUseID:                   opts.ToolUseID,
		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
		CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
		TranscriptLinesAtStart:      opts.CheckpointTranscriptStart,
		TokenUsage:                  opts.TokenUsage,
		InitialAttribution:          opts.InitialAttribution,
		Summary:                     redactSummary(opts.Summary),
		CLIVersion:                  buildinfo.Version,
	}

	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
	if err != nil {
		return nil, filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
	}
	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
	if err != nil {
		return nil, filePaths, err
	}
	entries = append(entries, object.TreeEntry{
		Name: paths.MetadataFileName,
		Mode: filemode.Regular,
		Hash: metadataHash,
	})
	filePaths.Metadata = "/" + paths.MetadataFileName

	return entries, filePaths, nil
}

// buildTranscriptEntries builds tree entries for the transcript (with chunking support).
func (s *GitStore) buildTranscriptEntries(opts WriteCommittedOptions) ([]object.TreeEntry, error) {
	transcript := opts.Transcript
	if len(transcript) == 0 && opts.TranscriptPath != "" {
		var readErr error
		transcript, readErr = os.ReadFile(opts.TranscriptPath)
		if readErr != nil {
			transcript = nil
		}
	}
	if len(transcript) == 0 {
		return nil, nil
	}

	transcript, err := redact.JSONLBytes(transcript)
	if err != nil {
		return nil, fmt.Errorf("failed to redact transcript secrets: %w", err)
	}

	chunks, err := agent.ChunkTranscript(transcript, opts.Agent)
	if err != nil {
		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
	}

	var entries []object.TreeEntry
	for i, chunk := range chunks {
		chunkName := agent.ChunkFileName(paths.TranscriptFileName, i)
		blobHash, err := CreateBlobFromContent(s.repo, chunk)
		if err != nil {
			return nil, err
		}
		entries = append(entries, object.TreeEntry{
			Name: chunkName,
			Mode: filemode.Regular,
			Hash: blobHash,
		})
	}

	// Content hash
	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
	if err != nil {
		return nil, err
	}
	entries = append(entries, object.TreeEntry{
		Name: paths.ContentHashFileName,
		Mode: filemode.Regular,
		Hash: hashBlob,
	})

	return entries, nil
}

// buildTaskSubtreeEntries builds tree entries for task-specific checkpoints.
// Returns entries to be placed under "tasks/<toolUseID>/" and the task metadata path.
func (s *GitStore) buildTaskSubtreeEntries(opts WriteCommittedOptions) ([]object.TreeEntry, string, error) {
	taskDirName := opts.ToolUseID

	if opts.IsIncremental {
		return s.buildIncrementalTaskEntries(opts, taskDirName)
	}
	return s.buildFinalTaskEntries(opts, taskDirName)
}

// buildIncrementalTaskEntries builds entries for an incremental task checkpoint.
func (s *GitStore) buildIncrementalTaskEntries(opts WriteCommittedOptions, taskDirName string) ([]object.TreeEntry, string, error) {
	incData, err := redact.JSONLBytes(opts.IncrementalData)
	if err != nil {
		return nil, "", fmt.Errorf("failed to redact incremental checkpoint: %w", err)
	}
	checkpoint := incrementalCheckpointData{
		Type:      opts.IncrementalType,
		ToolUseID: opts.ToolUseID,
		Timestamp: time.Now().UTC(),
		Data:      incData,
	}
	cpData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
	if err != nil {
		return nil, "", fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
	}
	cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
	if err != nil {
		return nil, "", fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
	}

	cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
	// The entry goes under tasks/<toolUseID>/checkpoints/<filename>
	// We return a flat entry path relative to the checkpoint root
	taskMetadataPath := "tasks/" + taskDirName + "/checkpoints/" + cpFilename
	return []object.TreeEntry{{
		Name: cpFilename,
		Mode: filemode.Regular,
		Hash: cpBlobHash,
	}}, taskMetadataPath, nil
}

// buildFinalTaskEntries builds entries for a final task checkpoint.
func (s *GitStore) buildFinalTaskEntries(opts WriteCommittedOptions, taskDirName string) ([]object.TreeEntry, string, error) {
	checkpoint := taskCheckpointData{
		SessionID:      opts.SessionID,
		ToolUseID:      opts.ToolUseID,
		CheckpointUUID: opts.CheckpointUUID,
		AgentID:        opts.AgentID,
	}
	checkpointData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
	if err != nil {
		return nil, "", fmt.Errorf("failed to marshal task checkpoint: %w", err)
	}
	blobHash, err := CreateBlobFromContent(s.repo, checkpointData)
	if err != nil {
		return nil, "", fmt.Errorf("failed to create task checkpoint blob: %w", err)
	}

	var entries []object.TreeEntry
	entries = append(entries, object.TreeEntry{
		Name: "checkpoint.json",
		Mode: filemode.Regular,
		Hash: blobHash,
	})

	// Write subagent transcript if available
	if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
		agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath)
		if readErr == nil {
			redacted, jsonlErr := redact.JSONLBytes(agentContent)
			if jsonlErr != nil {
				logging.Warn(context.Background(), "subagent transcript is not valid JSONL, falling back to plain redaction",
					slog.String("path", opts.SubagentTranscriptPath),
					slog.String("error", jsonlErr.Error()),
				)
				redacted = redact.Bytes(agentContent)
			}
			agentBlobHash, agentBlobErr := CreateBlobFromContent(s.repo, redacted)
			if agentBlobErr == nil {
				entries = append(entries, object.TreeEntry{
					Name: "agent-" + opts.AgentID + ".jsonl",
					Mode: filemode.Regular,
					Hash: agentBlobHash,
				})
			}
		}
	}

	taskMetadataPath := "tasks/" + taskDirName
	return entries, taskMetadataPath, nil
}

// buildMetadataDirEntries builds tree entries from a metadata directory on disk.
// Returns entries with names relative to the session subdirectory.
func (s *GitStore) buildMetadataDirEntries(metadataDir string) ([]object.TreeEntry, error) {
	var entries []object.TreeEntry
	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		linfo, lstatErr := os.Lstat(path)
		if lstatErr != nil {
			return fmt.Errorf("failed to lstat %s: %w", path, lstatErr)
		}
		if linfo.Mode()&os.ModeSymlink != 0 {
			if info.IsDir() {
				return filepath.SkipDir
			}
			return nil
		}
		if info.IsDir() {
			return nil
		}
		relPath, err := filepath.Rel(metadataDir, path)
		if err != nil {
			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
		}
		if strings.HasPrefix(relPath, "..") {
			return fmt.Errorf("path traversal detected: %s", relPath)
		}
		treePath := filepath.ToSlash(relPath)
		blobHash, mode, err := createRedactedBlobFromFile(s.repo, path, treePath)
		if err != nil {
			return fmt.Errorf("failed to create blob for %s: %w", path, err)
		}
		entries = append(entries, object.TreeEntry{
			Name: treePath,
			Mode: mode,
			Hash: blobHash,
		})
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to walk metadata directory: %w", err)
	}
	return entries, nil
}

