133→	// MergeKeepExisting: read existing tree, merge
134→	existingTree, err := repo.TreeObject(existingTreeHash)
135→	if err != nil {
136→		sorted := make([]object.TreeEntry, len(newEntries))
137→		copy(sorted, newEntries)
138→		sortTreeEntries(sorted)
139→		return storeTree(repo, sorted)
140→	}
141→
142→	// Build lookup of new entries by name
143→	newByName := make(map[string]object.TreeEntry, len(newEntries))
144→	for _, e := range newEntries {
145→		newByName[e.Name] = e
146→	}
147→
148→	// Build delete set
149→	deleteSet := make(map[string]bool, len(opts.DeleteNames))
150→	for _, name := range opts.DeleteNames {
151→		deleteSet[name] = true
152→	}
153→
154→	// Merge: keep existing unless overwritten or deleted
155→	merged := make([]object.TreeEntry, 0, len(existingTree.Entries)+len(newEntries))
156→	for _, existing := range existingTree.Entries {
157→		if deleteSet[existing.Name] {
158→			continue
159→		}
160→		if replacement, ok := newByName[existing.Name]; ok {
161→			merged = append(merged, replacement)
162→			delete(newByName, existing.Name)
163→		} else {
164→			merged = append(merged, existing)
165→		}
166→	}
167→	// Add remaining new entries (ones that didn't replace an existing entry)
168→	for _, e := range newEntries {
169→		if _, stillNew := newByName[e.Name]; stillNew {
170→			merged = append(merged, e)
171→		}
