178→// storeTree creates a git tree object from entries and stores it in the repo.
179→func storeTree(repo *git.Repository, entries []object.TreeEntry) (plumbing.Hash, error) {
180→	tree := &object.Tree{Entries: entries}
181→	obj := repo.Storer.NewEncodedObject()
182→	if err := tree.Encode(obj); err != nil {
183→		return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
184→	}
185→	hash, err := repo.Storer.SetEncodedObject(obj)
186→	if err != nil {
187→		return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
188→	}
189→	return hash, nil
190→}
