func TestApplyTreeChanges_MultipleDirectories(t *testing.T) {
	t.Parallel()
	repo, _ := git.PlainInit(t.TempDir(), true)

	blobA := storeBlob(t, repo, "file-a")
	blobB := storeBlob(t, repo, "file-b")
