	files := flattenTreeHelper(t, repo, newRoot, "")
	if files["a3/ckpt1/file.txt"] != blobNew {
		t.Error("a3/ckpt1/file.txt should have new hash")
	}
	if files["b7/ckpt2/file.txt"] != blobB {
		t.Error("b7/ckpt2/file.txt should be preserved")
	}
}

