 120→// flattenCheckpointEntries reads only the entries under a specific checkpoint path
 121→// from the sessions branch tree. This is O(files in checkpoint) instead of O(all checkpoints).
 122→// Returns an empty map if the checkpoint doesn't exist yet.
 123→func (s *GitStore) flattenCheckpointEntries(rootTreeHash plumbing.Hash, checkpointPath string) (map[string]object.TreeEntry, error) {
 124→	entries := make(map[string]object.TreeEntry)
 125→	if rootTreeHash == plumbing.ZeroHash {
 126→		return entries, nil
 127→	}
 128→
 129→	rootTree, err := s.repo.TreeObject(rootTreeHash)
 130→	if err != nil {
 131→		return entries, nil //nolint:nilerr // New tree, no existing entries
 132→	}
 133→
 134→	subtree, err := rootTree.Tree(checkpointPath)
 135→	if err != nil {
 136→		return entries, nil //nolint:nilerr // Checkpoint doesn't exist yet
 137→	}
 138→
 139→	// Flatten just this subtree with the full path prefix
 140→	if err := FlattenTree(s.repo, subtree, checkpointPath, entries); err != nil {
 141→		return nil, err
 142→	}
 143→	return entries, nil
 144→}
