 146→// spliceCheckpointSubtree builds a tree from checkpoint-local entries and installs it
 147→// at the correct shard location in the root tree using O(depth) tree surgery.
 148→// basePath is like "a3/b2c4d5e6f7/" (with trailing slash).
 149→// Returns the new root tree hash.
 150→func (s *GitStore) spliceCheckpointSubtree(rootTreeHash plumbing.Hash, checkpointID id.CheckpointID, basePath string, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
 151→	// Convert entries to relative paths (strip basePath prefix)
 152→	relEntries := make(map[string]object.TreeEntry, len(entries))
 153→	for path, entry := range entries {
 154→		relPath := strings.TrimPrefix(path, basePath)
 155→		if relPath == path {
 156→			continue // Entry doesn't have the expected prefix
 157→		}
 158→		relEntries[relPath] = entry
 159→	}
 160→
 161→	// Build the checkpoint subtree from relative entries
 162→	checkpointTreeHash, err := BuildTreeFromEntries(s.repo, relEntries)
 163→	if err != nil {
 164→		return plumbing.ZeroHash, fmt.Errorf("failed to build checkpoint subtree: %w", err)
 165→	}
 166→
 167→	// Splice into root tree at the shard path using tree surgery
 168→	// Path: ["a3"] with entry "b2c4d5e6f7" pointing to the checkpoint tree
 169→	shardPrefix := string(checkpointID[:2])
 170→	shardSuffix := string(checkpointID[2:])
 171→	return UpdateSubtree(s.repo, rootTreeHash, []string{shardPrefix}, []object.TreeEntry{
 172→		{Name: shardSuffix, Mode: filemode.Dir, Hash: checkpointTreeHash},
 173→	}, UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
 174→}
