 273→// writeStandardCheckpointEntries writes session files to numbered subdirectories and
 274→// maintains a CheckpointSummary at the root level with aggregated statistics.
 275→//
 276→// Structure:
 277→//
 278→//	basePath/
 279→//	├── metadata.json         # CheckpointSummary (aggregated stats)
 280→//	├── 1/                    # First session
 281→//	│   ├── metadata.json     # CommittedMetadata (session-specific, includes initial_attribution)
 282→//	│   ├── full.jsonl
 283→//	│   ├── prompt.txt
 284→//	│   ├── context.md
 285→//	│   └── content_hash.txt
 286→//	├── 2/                    # Second session
 287→//	└── ...
 288→func (s *GitStore) writeStandardCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
 289→	// Read existing summary to get current session count
 290→	var existingSummary *CheckpointSummary
 291→	metadataPath := basePath + paths.MetadataFileName
 292→	if entry, exists := entries[metadataPath]; exists {
 293→		existing, err := s.readSummaryFromBlob(entry.Hash)
 294→		if err == nil {
 295→			existingSummary = existing
 296→		}
 297→	}
 298→
 299→	// Determine session index: reuse existing slot if session ID matches, otherwise append
 300→	sessionIndex := s.findSessionIndex(basePath, existingSummary, entries, opts.SessionID)
 301→
 302→	// Write session files to numbered subdirectory
 303→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
 304→	sessionFilePaths, err := s.writeSessionToSubdirectory(opts, sessionPath, entries)
 305→	if err != nil {
 306→		return err
 307→	}
 308→
 309→	// Copy additional metadata files from directory if specified (to session subdirectory)
 310→	if opts.MetadataDir != "" {
 311→		if err := s.copyMetadataDir(opts.MetadataDir, sessionPath, entries); err != nil {
 312→			return fmt.Errorf("failed to copy metadata directory: %w", err)
 313→		}
 314→	}
 315→
 316→	// Build the sessions array
 317→	var sessions []SessionFilePaths
 318→	if existingSummary != nil {
 319→		sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
 320→		copy(sessions, existingSummary.Sessions)
 321→	} else {
 322→		sessions = make([]SessionFilePaths, 1)
 323→	}
 324→	sessions[sessionIndex] = sessionFilePaths
 325→
 326→	// Update root metadata.json with CheckpointSummary
 327→	return s.writeCheckpointSummary(opts, basePath, entries, sessions)
 328→}
 329→
 330→// writeSessionToSubdirectory writes a single session's files to a numbered subdirectory.
 331→// Returns the absolute file paths from the git tree root for the sessions map.
 332→func (s *GitStore) writeSessionToSubdirectory(opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
 333→	filePaths := SessionFilePaths{}
 334→
 335→	// Clear any existing entries at this path so stale files from a previous
 336→	// write (e.g. prompt.txt, context.md) don't persist on overwrite.
 337→	for key := range entries {
 338→		if strings.HasPrefix(key, sessionPath) {
 339→			delete(entries, key)
 340→		}
 341→	}
 342→
 343→	// Write transcript
 344→	if err := s.writeTranscript(opts, sessionPath, entries); err != nil {
 345→		return filePaths, err
 346→	}
 347→	filePaths.Transcript = "/" + sessionPath + paths.TranscriptFileName
 348→	filePaths.ContentHash = "/" + sessionPath + paths.ContentHashFileName
 349→
 350→	// Write prompts
 351→	if len(opts.Prompts) > 0 {
 352→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
 353→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
 354→		if err != nil {
 355→			return filePaths, err
 356→		}
 357→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
 358→			Name: sessionPath + paths.PromptFileName,
 359→			Mode: filemode.Regular,
 360→			Hash: blobHash,
 361→		}
 362→		filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
 363→	}
 364→
 365→	// Write context
 366→	if len(opts.Context) > 0 {
 367→		blobHash, err := CreateBlobFromContent(s.repo, redact.Bytes(opts.Context))
 368→		if err != nil {
 369→			return filePaths, err
 370→		}
 371→		entries[sessionPath+paths.ContextFileName] = object.TreeEntry{
 372→			Name: sessionPath + paths.ContextFileName,
 373→			Mode: filemode.Regular,
 374→			Hash: blobHash,
 375→		}
 376→		filePaths.Context = "/" + sessionPath + paths.ContextFileName
 377→	}
 378→
 379→	// Write session-level metadata.json (CommittedMetadata with all fields including initial_attribution)
 380→	sessionMetadata := CommittedMetadata{
 381→		CheckpointID:                opts.CheckpointID,
 382→		SessionID:                   opts.SessionID,
 383→		Strategy:                    opts.Strategy,
 384→		CreatedAt:                   time.Now().UTC(),
 385→		Branch:                      opts.Branch,
 386→		CheckpointsCount:            opts.CheckpointsCount,
 387→		FilesTouched:                opts.FilesTouched,
 388→		Agent:                       opts.Agent,
 389→		TurnID:                      opts.TurnID,
 390→		IsTask:                      opts.IsTask,
 391→		ToolUseID:                   opts.ToolUseID,
 392→		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
 393→		CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
 394→		TranscriptLinesAtStart:      opts.CheckpointTranscriptStart, // Deprecated: kept for backward compat
 395→		TokenUsage:                  opts.TokenUsage,
 396→		InitialAttribution:          opts.InitialAttribution,
 397→		Summary:                     redactSummary(opts.Summary),
 398→		CLIVersion:                  buildinfo.Version,
 399→	}
 400→
 401→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
 402→	if err != nil {
 403→		return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
 404→	}
 405→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
 406→	if err != nil {
 407→		return filePaths, err
 408→	}
 409→	entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
 410→		Name: sessionPath + paths.MetadataFileName,
 411→		Mode: filemode.Regular,
 412→		Hash: metadataHash,
 413→	}
 414→	filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
 415→
 416→	return filePaths, nil
 417→}
