 419→// writeCheckpointSummary writes the root-level CheckpointSummary with aggregated statistics.
 420→// sessions is the complete sessions array (already built by the caller).
 421→func (s *GitStore) writeCheckpointSummary(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, sessions []SessionFilePaths) error {
 422→	checkpointsCount, filesTouched, tokenUsage, err :=
 423→		s.reaggregateFromEntries(basePath, len(sessions), entries)
 424→	if err != nil {
 425→		return fmt.Errorf("failed to aggregate session stats: %w", err)
 426→	}
 427→
 428→	summary := CheckpointSummary{
 429→		CheckpointID:     opts.CheckpointID,
 430→		CLIVersion:       buildinfo.Version,
 431→		Strategy:         opts.Strategy,
 432→		Branch:           opts.Branch,
 433→		CheckpointsCount: checkpointsCount,
 434→		FilesTouched:     filesTouched,
 435→		Sessions:         sessions,
 436→		TokenUsage:       tokenUsage,
 437→	}
 438→
 439→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
 440→	if err != nil {
 441→		return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
 442→	}
 443→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
 444→	if err != nil {
 445→		return err
 446→	}
 447→	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
 448→		Name: basePath + paths.MetadataFileName,
 449→		Mode: filemode.Regular,
 450→		Hash: metadataHash,
 451→	}
 452→	return nil
 453→}
