 455→// findSessionIndex returns the index of an existing session with the given ID,
 456→// or the next available index if not found. This prevents duplicate session entries.
 457→func (s *GitStore) findSessionIndex(basePath string, existingSummary *CheckpointSummary, entries map[string]object.TreeEntry, sessionID string) int {
 458→	if existingSummary == nil {
 459→		return 0
 460→	}
 461→	for i := range len(existingSummary.Sessions) {
 462→		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
 463→		if entry, exists := entries[path]; exists {
 464→			meta, err := s.readMetadataFromBlob(entry.Hash)
 465→			if err != nil {
 466→				logging.Warn(context.Background(), "failed to read session metadata during dedup check",
 467→					slog.Int("session_index", i),
 468→					slog.String("session_id", sessionID),
 469→					slog.String("error", err.Error()),
 470→				)
 471→				continue
 472→			}
 473→			if meta.SessionID == sessionID {
 474→				return i
 475→			}
 476→		}
 477→	}
 478→	return len(existingSummary.Sessions)
 479→}
 480→
 481→// reaggregateFromEntries reads all session metadata from the entries map and
 482→// reaggregates CheckpointsCount, FilesTouched, and TokenUsage.
 483→func (s *GitStore) reaggregateFromEntries(basePath string, sessionCount int, entries map[string]object.TreeEntry) (int, []string, *agent.TokenUsage, error) {
 484→	var totalCount int
 485→	var allFiles []string
 486→	var totalTokens *agent.TokenUsage
 487→
 488→	for i := range sessionCount {
 489→		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
 490→		entry, exists := entries[path]
 491→		if !exists {
 492→			return 0, nil, nil, fmt.Errorf("session %d metadata not found at %s", i, path)
 493→		}
 494→		meta, err := s.readMetadataFromBlob(entry.Hash)
 495→		if err != nil {
 496→			return 0, nil, nil, fmt.Errorf("failed to read session %d metadata: %w", i, err)
 497→		}
 498→		totalCount += meta.CheckpointsCount
 499→		allFiles = mergeFilesTouched(allFiles, meta.FilesTouched)
 500→		totalTokens = aggregateTokenUsage(totalTokens, meta.TokenUsage)
 501→	}
 502→
 503→	return totalCount, allFiles, totalTokens, nil
 504→}
