 506→// readJSONFromBlob reads JSON from a blob hash and decodes it to the given type.
 507→func readJSONFromBlob[T any](repo *git.Repository, hash plumbing.Hash) (*T, error) {
 508→	blob, err := repo.BlobObject(hash)
 509→	if err != nil {
 510→		return nil, fmt.Errorf("failed to get blob: %w", err)
 511→	}
 512→
 513→	reader, err := blob.Reader()
 514→	if err != nil {
 515→		return nil, fmt.Errorf("failed to get blob reader: %w", err)
 516→	}
 517→	defer reader.Close()
 518→
 519→	var result T
 520→	if err := json.NewDecoder(reader).Decode(&result); err != nil {
 521→		return nil, fmt.Errorf("failed to decode: %w", err)
 522→	}
 523→
 524→	return &result, nil
 525→}
