 532→// aggregateTokenUsage sums two TokenUsage structs.
 533→// Returns nil if both inputs are nil.
 534→func aggregateTokenUsage(a, b *agent.TokenUsage) *agent.TokenUsage {
 535→	if a == nil && b == nil {
 536→		return nil
 537→	}
 538→	result := &agent.TokenUsage{}
 539→	if a != nil {
 540→		result.InputTokens = a.InputTokens
 541→		result.CacheCreationTokens = a.CacheCreationTokens
 542→		result.CacheReadTokens = a.CacheReadTokens
 543→		result.OutputTokens = a.OutputTokens
 544→		result.APICallCount = a.APICallCount
 545→	}
 546→	if b != nil {
 547→		result.InputTokens += b.InputTokens
 548→		result.CacheCreationTokens += b.CacheCreationTokens
 549→		result.CacheReadTokens += b.CacheReadTokens
 550→		result.OutputTokens += b.OutputTokens
 551→		result.APICallCount += b.APICallCount
 552→	}
 553→	return result
 554→}
