 634→// redactSummary returns a copy of the summary with text fields redacted.
 635→// Structural fields (Path, Line, EndLine) are preserved.
 636→// NOTE: When adding new text fields to Summary, LearningsSummary, or CodeLearning,
 637→// update this function to include them in redaction.
 638→func redactSummary(s *Summary) *Summary {
 639→	if s == nil {
 640→		return nil
 641→	}
 642→	return &Summary{
 643→		Intent:    redact.String(s.Intent),
 644→		Outcome:   redact.String(s.Outcome),
 645→		Friction:  redactStringSlice(s.Friction),
 646→		OpenItems: redactStringSlice(s.OpenItems),
 647→		Learnings: LearningsSummary{
 648→			Repo:     redactStringSlice(s.Learnings.Repo),
 649→			Workflow: redactStringSlice(s.Learnings.Workflow),
 650→			Code:     redactCodeLearnings(s.Learnings.Code),
 651→		},
 652→	}
 653→}
 654→
 655→// redactStringSlice applies redact.String to each element.
 656→func redactStringSlice(ss []string) []string {
 657→	if ss == nil {
 658→		return nil
 659→	}
 660→	out := make([]string, len(ss))
 661→	for i, s := range ss {
 662→		out[i] = redact.String(s)
 663→	}
 664→	return out
 665→}
 666→
 667→// redactCodeLearnings redacts only the Finding field, preserving Path/Line/EndLine.
 668→func redactCodeLearnings(cls []CodeLearning) []CodeLearning {
 669→	if cls == nil {
 670→		return nil
 671→	}
 672→	out := make([]CodeLearning, len(cls))
 673→	for i, cl := range cls {
 674→		out[i] = CodeLearning{
 675→			Path:    cl.Path,
 676→			Line:    cl.Line,
 677→			EndLine: cl.EndLine,
 678→			Finding: redact.String(cl.Finding),
 679→		}
 680→	}
 681→	return out
 682→}
