 782→// ReadSessionContent reads the actual content for a specific session within a checkpoint.
 783→// sessionIndex is 0-based (0 for first session, 1 for second, etc.).
 784→// Returns the session's metadata, transcript, prompts, and context.
 785→// Returns an error if the checkpoint or session doesn't exist.
 786→func (s *GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
 787→	_ = ctx // Reserved for future use
 788→
 789→	tree, err := s.getSessionsBranchTree()
 790→	if err != nil {
 791→		return nil, ErrCheckpointNotFound
 792→	}
 793→
 794→	checkpointPath := checkpointID.Path()
 795→	checkpointTree, err := tree.Tree(checkpointPath)
 796→	if err != nil {
 797→		return nil, ErrCheckpointNotFound
 798→	}
 799→
 800→	// Get the session subdirectory
 801→	sessionDir := strconv.Itoa(sessionIndex)
 802→	sessionTree, err := checkpointTree.Tree(sessionDir)
 803→	if err != nil {
 804→		return nil, fmt.Errorf("session %d not found: %w", sessionIndex, err)
 805→	}
 806→
 807→	result := &SessionContent{}
 808→
 809→	// Read session-specific metadata
 810→	var agentType agent.AgentType
 811→	if metadataFile, fileErr := sessionTree.File(paths.MetadataFileName); fileErr == nil {
 812→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
 813→			if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr == nil {
 814→				agentType = result.Metadata.Agent
 815→			}
 816→		}
 817→	}
 818→
 819→	// Read transcript
 820→	if transcript, transcriptErr := readTranscriptFromTree(sessionTree, agentType); transcriptErr == nil && transcript != nil {
 821→		result.Transcript = transcript
 822→	}
 823→
 824→	// Read prompts
 825→	if file, fileErr := sessionTree.File(paths.PromptFileName); fileErr == nil {
 826→		if content, contentErr := file.Contents(); contentErr == nil {
 827→			result.Prompts = content
 828→		}
 829→	}
 830→
 831→	// Read context
 832→	if file, fileErr := sessionTree.File(paths.ContextFileName); fileErr == nil {
 833→		if content, contentErr := file.Contents(); contentErr == nil {
 834→			result.Context = content
 835→		}
 836→	}
 837→
 838→	return result, nil
 839→}
