 841→// ReadLatestSessionContent is a convenience method that reads the latest session's content.
 842→// This is equivalent to ReadSessionContent(ctx, checkpointID, len(summary.Sessions)-1).
 843→func (s *GitStore) ReadLatestSessionContent(ctx context.Context, checkpointID id.CheckpointID) (*SessionContent, error) {
 844→	summary, err := s.ReadCommitted(ctx, checkpointID)
 845→	if err != nil {
 846→		return nil, err
 847→	}
 848→	if summary == nil {
 849→		return nil, ErrCheckpointNotFound
 850→	}
 851→	if len(summary.Sessions) == 0 {
 852→		return nil, fmt.Errorf("checkpoint has no sessions: %s", checkpointID)
