1115→// UpdateCommitted replaces the transcript, prompts, and context for an existing
1116→// committed checkpoint. Uses replace semantics: the full session transcript is
1117→// written, replacing whatever was stored at initial condensation time.
1118→//
1119→// This is called at stop time to finalize all checkpoints from the current turn
1120→// with the complete session transcript (from prompt to stop event).
1121→//
1122→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
1123→func (s *GitStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error {
1124→	if opts.CheckpointID.IsEmpty() {
1125→		return errors.New("invalid update options: checkpoint ID is required")
1126→	}
1127→
1128→	// Ensure sessions branch exists
1129→	if err := s.ensureSessionsBranch(); err != nil {
1130→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
1131→	}
1132→
1133→	// Get branch ref and root tree hash (O(1), no flatten)
1134→	parentHash, rootTreeHash, err := s.getSessionsBranchRef()
1135→	if err != nil {
1136→		return err
1137→	}
1138→
1139→	// Flatten only the checkpoint subtree
1140→	basePath := opts.CheckpointID.Path() + "/"
1141→	checkpointPath := opts.CheckpointID.Path()
1142→	entries, err := s.flattenCheckpointEntries(rootTreeHash, checkpointPath)
1143→	if err != nil {
1144→		return err
1145→	}
1146→
1147→	// Read root CheckpointSummary to find the session slot
1148→	rootMetadataPath := basePath + paths.MetadataFileName
1149→	entry, exists := entries[rootMetadataPath]
1150→	if !exists {
1151→		return ErrCheckpointNotFound
1152→	}
1153→
1154→	checkpointSummary, err := s.readSummaryFromBlob(entry.Hash)
1155→	if err != nil {
1156→		return fmt.Errorf("failed to read checkpoint summary: %w", err)
1157→	}
1158→	if len(checkpointSummary.Sessions) == 0 {
1159→		return ErrCheckpointNotFound
1160→	}
1161→
1162→	// Find session index matching opts.SessionID
1163→	sessionIndex := -1
1164→	for i := range len(checkpointSummary.Sessions) {
1165→		metaPath := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
1166→		if metaEntry, metaExists := entries[metaPath]; metaExists {
1167→			meta, metaErr := s.readMetadataFromBlob(metaEntry.Hash)
1168→			if metaErr == nil && meta.SessionID == opts.SessionID {
1169→				sessionIndex = i
1170→				break
1171→			}
1172→		}
1173→	}
1174→	if sessionIndex == -1 {
1175→		// Fall back to latest session; log so mismatches are diagnosable.
1176→		sessionIndex = len(checkpointSummary.Sessions) - 1
1177→		logging.Debug(ctx, "UpdateCommitted: session ID not found, falling back to latest",
1178→			slog.String("session_id", opts.SessionID),
1179→			slog.String("checkpoint_id", string(opts.CheckpointID)),
1180→			slog.Int("fallback_index", sessionIndex),
1181→		)
1182→	}
1183→
1184→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
1185→
1186→	// Replace transcript (full replace, not append)
1187→	// Apply redaction as safety net (caller should redact, but we ensure it here)
1188→	if len(opts.Transcript) > 0 {
1189→		transcript, err := redact.JSONLBytes(opts.Transcript)
1190→		if err != nil {
1191→			return fmt.Errorf("failed to redact transcript secrets: %w", err)
1192→		}
1193→		if err := s.replaceTranscript(transcript, opts.Agent, sessionPath, entries); err != nil {
1194→			return fmt.Errorf("failed to replace transcript: %w", err)
1195→		}
1196→	}
1197→
1198→	// Replace prompts (apply redaction as safety net)
1199→	if len(opts.Prompts) > 0 {
1200→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
1201→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
1202→		if err != nil {
1203→			return fmt.Errorf("failed to create prompt blob: %w", err)
1204→		}
1205→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
1206→			Name: sessionPath + paths.PromptFileName,
1207→			Mode: filemode.Regular,
1208→			Hash: blobHash,
1209→		}
1210→	}
1211→
1212→	// Replace context (apply redaction as safety net)
1213→	if len(opts.Context) > 0 {
1214→		contextBlob, err := CreateBlobFromContent(s.repo, redact.Bytes(opts.Context))
1215→		if err != nil {
1216→			return fmt.Errorf("failed to create context blob: %w", err)
1217→		}
1218→		entries[sessionPath+paths.ContextFileName] = object.TreeEntry{
1219→			Name: sessionPath + paths.ContextFileName,
1220→			Mode: filemode.Regular,
1221→			Hash: contextBlob,
1222→		}
1223→	}
1224→
1225→	// Build checkpoint subtree and splice into root (O(depth) tree surgery)
1226→	newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
1227→	if err != nil {
1228→		return err
1229→	}
1230→
1231→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
1232→	commitMsg := fmt.Sprintf("Finalize transcript for Checkpoint: %s", opts.CheckpointID)
1233→	newCommitHash, err := s.createCommit(newTreeHash, parentHash, commitMsg, authorName, authorEmail)
1234→	if err != nil {
1235→		return err
1236→	}
1237→
1238→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1239→	newRef := plumbing.NewHashReference(refName, newCommitHash)
1240→	if err := s.repo.Storer.SetReference(newRef); err != nil {
1241→		return fmt.Errorf("failed to set branch reference: %w", err)
1242→	}
1243→
1244→	return nil
1245→}
