1294→// ensureSessionsBranch ensures the entire/checkpoints/v1 branch exists.
1295→func (s *GitStore) ensureSessionsBranch() error {
1296→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1297→	_, err := s.repo.Reference(refName, true)
1298→	if err == nil {
1299→		return nil // Branch exists
1300→	}
1301→
1302→	// Create orphan branch with empty tree
1303→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
1304→	if err != nil {
1305→		return err
1306→	}
1307→
1308→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
1309→	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
1310→	if err != nil {
1311→		return err
1312→	}
1313→
1314→	newRef := plumbing.NewHashReference(refName, commitHash)
1315→	if err := s.repo.Storer.SetReference(newRef); err != nil {
1316→		return fmt.Errorf("failed to set branch reference: %w", err)
1317→	}
1318→	return nil
1319→}
