648→// TestUpdateSubtree_EquivalenceWithFlattenRebuild verifies that UpdateSubtree
649→// produces the same result as the old FlattenTree + modify + BuildTreeFromEntries approach.
650→func TestUpdateSubtree_EquivalenceWithFlattenRebuild(t *testing.T) {
651→	t.Parallel()
652→	repo := mustInitBareRepo(t)
653→
654→	// Build a realistic sharded tree with multiple checkpoints
655→	blobs := make([]plumbing.Hash, 5)
656→	for i := range blobs {
657→		blobs[i] = storeBlob(t, repo, fmt.Sprintf("content-%d", i))
658→	}
659→
660→	// Build: a3/ckpt1/{meta.json, full.jsonl}, a3/ckpt2/{meta.json}, b7/ckpt3/{meta.json}
661→	ckpt1 := mustStoreTree(t, repo, []object.TreeEntry{
662→		{Name: "full.jsonl", Mode: filemode.Regular, Hash: blobs[1]},
663→		{Name: "meta.json", Mode: filemode.Regular, Hash: blobs[0]},
664→	})
665→	ckpt2 := mustStoreTree(t, repo, []object.TreeEntry{
666→		{Name: "meta.json", Mode: filemode.Regular, Hash: blobs[2]},
667→	})
668→	ckpt3 := mustStoreTree(t, repo, []object.TreeEntry{
669→		{Name: "meta.json", Mode: filemode.Regular, Hash: blobs[3]},
670→	})
671→	shardA3 := mustStoreTree(t, repo, []object.TreeEntry{
672→		{Name: "ckpt1", Mode: filemode.Dir, Hash: ckpt1},
673→		{Name: "ckpt2", Mode: filemode.Dir, Hash: ckpt2},
674→	})
675→	shardB7 := mustStoreTree(t, repo, []object.TreeEntry{
676→		{Name: "ckpt3", Mode: filemode.Dir, Hash: ckpt3},
677→	})
678→	rootTree := mustStoreTree(t, repo, []object.TreeEntry{
679→		{Name: "a3", Mode: filemode.Dir, Hash: shardA3},
680→		{Name: "b7", Mode: filemode.Dir, Hash: shardB7},
681→	})
682→
683→	// Now add a new checkpoint at a3/newckpt/ using tree surgery
684→	newBlob := storeBlob(t, repo, "new-checkpoint")
685→	surgeryResult, err := UpdateSubtree(repo, rootTree, []string{"a3", "newckpt"}, []object.TreeEntry{
686→		{Name: "meta.json", Mode: filemode.Regular, Hash: newBlob},
687→	}, UpdateSubtreeOptions{})
688→	if err != nil {
689→		t.Fatalf("UpdateSubtree() error = %v", err)
690→	}
691→
692→	// Do the same with FlattenTree + BuildTreeFromEntries
693→	tree := mustTreeObject(t, repo, rootTree)
694→	flatEntries := make(map[string]object.TreeEntry)
695→	if err := FlattenTree(repo, tree, "", flatEntries); err != nil {
696→		t.Fatalf("FlattenTree() error = %v", err)
697→	}
698→	flatEntries["a3/newckpt/meta.json"] = object.TreeEntry{
699→		Name: "meta.json",
700→		Mode: filemode.Regular,
701→		Hash: newBlob,
702→	}
703→	flatResult, err := BuildTreeFromEntries(repo, flatEntries)
704→	if err != nil {
705→		t.Fatalf("BuildTreeFromEntries() error = %v", err)
706→	}
707→
708→	// Both approaches should produce the exact same tree hash
709→	if surgeryResult != flatResult {
710→		t.Errorf("tree surgery result (%s) != flatten+rebuild result (%s)", surgeryResult, flatResult)
711→
712→		// Debug: show both trees
713→		surgeryFiles := flattenTreeHelper(t, repo, surgeryResult, "")
714→		flatFiles := flattenTreeHelper(t, repo, flatResult, "")
715→		t.Logf("Surgery files: %v", surgeryFiles)
716→		t.Logf("Flat files: %v", flatFiles)
717→	}
718→}
