119→// benchUpdateSubtreeTreeSurgery benchmarks adding a checkpoint to a metadata tree
120→// using UpdateSubtree (O(depth) tree surgery).
121→func benchUpdateSubtreeTreeSurgery(priorCheckpoints int) func(*testing.B) {
122→	return func(b *testing.B) {
123→		repo := benchInitBareRepo(b)
124→		rootTree := buildShardedMetadataTree(b, repo, priorCheckpoints)
125→
126→		// Prepare the new checkpoint data (5 files)
127→		newBlobs := make([]plumbing.Hash, 5)
128→		for i := range newBlobs {
129→			newBlobs[i] = benchCreateBlob(b, repo, fmt.Sprintf("new checkpoint file %d content", i))
130→		}
131→
132→		// Build the checkpoint subtree once
133→		cpEntries := make(map[string]object.TreeEntry, 5)
134→		for i, name := range []string{"metadata.json", "0/metadata.json", "0/full.jsonl", "0/prompt.txt", "0/content_hash.txt"} {
135→			cpEntries[name] = object.TreeEntry{
136→				Name: name,
137→				Mode: filemode.Regular,
138→				Hash: newBlobs[i],
139→			}
140→		}
141→		cpTreeHash, err := checkpoint.BuildTreeFromEntries(repo, cpEntries)
142→		if err != nil {
143→			b.Fatalf("build checkpoint tree: %v", err)
144→		}
145→
146→		shardPrefix := "ff" // Use a shard that likely doesn't exist yet
147→		shardSuffix := "newckpt1234"
148→
149→		b.ResetTimer()
150→		for range b.N {
151→			_, err := checkpoint.UpdateSubtree(repo, rootTree, []string{shardPrefix}, []object.TreeEntry{
152→				{Name: shardSuffix, Mode: filemode.Dir, Hash: cpTreeHash},
153→			}, checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.MergeKeepExisting})
154→			if err != nil {
155→				b.Fatalf("UpdateSubtree: %v", err)
156→			}
157→		}
158→	}
159→}
