161→// benchUpdateSubtreeFlattenRebuild benchmarks the old approach: flatten entire tree,
162→// add new entries, rebuild from scratch. O(total checkpoints).
163→func benchUpdateSubtreeFlattenRebuild(priorCheckpoints int) func(*testing.B) {
164→	return func(b *testing.B) {
165→		repo := benchInitBareRepo(b)
166→		rootTree := buildShardedMetadataTree(b, repo, priorCheckpoints)
167→
168→		// Prepare the new checkpoint entries
169→		newBlobs := make([]plumbing.Hash, 5)
170→		for i := range newBlobs {
171→			newBlobs[i] = benchCreateBlob(b, repo, fmt.Sprintf("new checkpoint file %d content", i))
172→		}
173→		newFiles := []struct {
174→			path string
175→			hash plumbing.Hash
176→		}{
177→			{"ff/newckpt1234/metadata.json", newBlobs[0]},
178→			{"ff/newckpt1234/0/metadata.json", newBlobs[1]},
179→			{"ff/newckpt1234/0/full.jsonl", newBlobs[2]},
180→			{"ff/newckpt1234/0/prompt.txt", newBlobs[3]},
181→			{"ff/newckpt1234/0/content_hash.txt", newBlobs[4]},
182→		}
183→
184→		b.ResetTimer()
185→		for range b.N {
186→			// Flatten entire tree
187→			tree, err := repo.TreeObject(rootTree)
188→			if err != nil {
189→				b.Fatalf("read tree: %v", err)
190→			}
191→			entries := make(map[string]object.TreeEntry)
192→			if err := checkpoint.FlattenTree(repo, tree, "", entries); err != nil {
193→				b.Fatalf("FlattenTree: %v", err)
194→			}
195→
196→			// Add new entries
197→			for _, f := range newFiles {
198→				entries[f.path] = object.TreeEntry{
199→					Name: f.path,
200→					Mode: filemode.Regular,
201→					Hash: f.hash,
202→				}
203→			}
204→
205→			// Rebuild entire tree
206→			_, err = checkpoint.BuildTreeFromEntries(repo, entries)
207→			if err != nil {
208→				b.Fatalf("BuildTreeFromEntries: %v", err)
209→			}
210→		}
211→	}
212→}
