214→// --- ApplyTreeChanges benchmarks (working tree / shadow branch path) ---
215→// Two dimensions: base tree size (total files) and number of changes.
216→
217→func BenchmarkApplyTreeChanges(b *testing.B) {
218→	// Dimension 1: Varying base tree size with fixed number of changes
219→	for _, fileCount := range []int{10, 100, 500} {
220→		b.Run(fmt.Sprintf("Files_%d_Changes_3/TreeSurgery", fileCount), benchApplyTreeChangesTreeSurgery(fileCount, 3))
221→		b.Run(fmt.Sprintf("Files_%d_Changes_3/FlattenRebuild", fileCount), benchApplyTreeChangesFlattenRebuild(fileCount, 3))
222→	}
223→
224→	// Dimension 2: Varying number of changes with fixed base tree size
225→	for _, changeCount := range []int{1, 5, 20, 50} {
226→		b.Run(fmt.Sprintf("Files_200_Changes_%d/TreeSurgery", changeCount), benchApplyTreeChangesTreeSurgery(200, changeCount))
227→		b.Run(fmt.Sprintf("Files_200_Changes_%d/FlattenRebuild", changeCount), benchApplyTreeChangesFlattenRebuild(200, changeCount))
228→	}
229→}
