231→// benchApplyTreeChangesTreeSurgery benchmarks modifying files in a tree
232→// using ApplyTreeChanges (only touches affected subtrees).
233→func benchApplyTreeChangesTreeSurgery(fileCount, changeCount int) func(*testing.B) {
234→	return func(b *testing.B) {
235→		repo := benchInitBareRepo(b)
236→		rootTree := buildFlatFileTree(b, repo, fileCount)
237→
238→		// Prepare changes: modify files spread across directories
239→		changes := make([]checkpoint.TreeChange, 0, changeCount)
240→		dirs := []string{"src", "pkg", "internal", "cmd", "api"}
241→		for i := range changeCount {
242→			dir := dirs[i%len(dirs)]
243→			fileIdx := i % fileCount
244→			path := fmt.Sprintf("%s/file_%04d.go", dir, fileIdx)
245→			newBlob := benchCreateBlob(b, repo, fmt.Sprintf("modified content %d\n", i))
246→			changes = append(changes, checkpoint.TreeChange{
247→				Path: path,
248→				Entry: &object.TreeEntry{
249→					Name: fmt.Sprintf("file_%04d.go", fileIdx),
250→					Mode: filemode.Regular,
251→					Hash: newBlob,
252→				},
253→			})
254→		}
255→
256→		b.ResetTimer()
257→		for range b.N {
258→			_, err := checkpoint.ApplyTreeChanges(repo, rootTree, changes)
259→			if err != nil {
260→				b.Fatalf("ApplyTreeChanges: %v", err)
261→			}
262→		}
263→	}
264→}
