266→// benchApplyTreeChangesFlattenRebuild benchmarks the old approach for working tree
267→// modifications: flatten, modify, rebuild.
268→func benchApplyTreeChangesFlattenRebuild(fileCount, changeCount int) func(*testing.B) {
269→	return func(b *testing.B) {
270→		repo := benchInitBareRepo(b)
271→		rootTree := buildFlatFileTree(b, repo, fileCount)
272→
273→		// Prepare changes
274→		type change struct {
275→			path string
276→			hash plumbing.Hash
277→		}
278→		changes := make([]change, 0, changeCount)
279→		dirs := []string{"src", "pkg", "internal", "cmd", "api"}
280→		for i := range changeCount {
281→			dir := dirs[i%len(dirs)]
282→			fileIdx := i % fileCount
283→			path := fmt.Sprintf("%s/file_%04d.go", dir, fileIdx)
284→			newBlob := benchCreateBlob(b, repo, fmt.Sprintf("modified content %d\n", i))
285→			changes = append(changes, change{path: path, hash: newBlob})
286→		}
287→
288→		b.ResetTimer()
289→		for range b.N {
290→			// Flatten entire tree
291→			tree, err := repo.TreeObject(rootTree)
292→			if err != nil {
293→				b.Fatalf("read tree: %v", err)
294→			}
295→			entries := make(map[string]object.TreeEntry)
296→			if err := checkpoint.FlattenTree(repo, tree, "", entries); err != nil {
297→				b.Fatalf("FlattenTree: %v", err)
298→			}
299→
300→			// Apply changes
301→			for _, c := range changes {
302→				entries[c.path] = object.TreeEntry{
303→					Name: c.path,
304→					Mode: filemode.Regular,
305→					Hash: c.hash,
306→				}
307→			}
308→
309→			// Rebuild
310→			_, err = checkpoint.BuildTreeFromEntries(repo, entries)
311→			if err != nil {
312→				b.Fatalf("BuildTreeFromEntries: %v", err)
313→			}
314→		}
315→	}
316→}
