 217→// writeFinalTaskCheckpoint writes the final checkpoint.json and subagent transcript.
 218→func (s *GitStore) writeFinalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
 219→	checkpoint := taskCheckpointData{
 220→		SessionID:      opts.SessionID,
 221→		ToolUseID:      opts.ToolUseID,
 222→		CheckpointUUID: opts.CheckpointUUID,
 223→		AgentID:        opts.AgentID,
 224→	}
 225→	checkpointData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
 226→	if err != nil {
 227→		return "", fmt.Errorf("failed to marshal task checkpoint: %w", err)
 228→	}
 229→	blobHash, err := CreateBlobFromContent(s.repo, checkpointData)
 230→	if err != nil {
 231→		return "", fmt.Errorf("failed to create task checkpoint blob: %w", err)
 232→	}
 233→
 234→	checkpointFile := taskPath + "checkpoint.json"
 235→	entries[checkpointFile] = object.TreeEntry{
 236→		Name: checkpointFile,
 237→		Mode: filemode.Regular,
 238→		Hash: blobHash,
 239→	}
 240→
 241→	// Write subagent transcript if available
 242→	if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
 243→		agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath)
 244→		if readErr == nil {
 245→			// Try JSONL-aware redaction first; fall back to plain string redaction
 246→			// if the content is not valid JSONL (avoids silently dropping the transcript).
 247→			redacted, jsonlErr := redact.JSONLBytes(agentContent)
 248→			if jsonlErr != nil {
 249→				logging.Warn(context.Background(), "subagent transcript is not valid JSONL, falling back to plain redaction",
 250→					slog.String("path", opts.SubagentTranscriptPath),
 251→					slog.String("error", jsonlErr.Error()),
 252→				)
 253→				redacted = redact.Bytes(agentContent)
 254→			}
 255→			agentContent = redacted
 256→
 257→			agentBlobHash, agentBlobErr := CreateBlobFromContent(s.repo, agentContent)
 258→			if agentBlobErr == nil {
 259→				agentPath := taskPath + "agent-" + opts.AgentID + ".jsonl"
 260→				entries[agentPath] = object.TreeEntry{
 261→					Name: agentPath,
 262→					Mode: filemode.Regular,
 263→					Hash: agentBlobHash,
 264→				}
 265→			}
 266→		}
 267→	}
 268→
 269→	// Return task path without trailing slash
 270→	return taskPath[:len(taskPath)-1], nil
 271→}
