 689→// buildCommitMessage constructs the commit message with proper trailers.
 690→// The commit subject is always "Checkpoint: <id>" for consistency.
 691→// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
 692→func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
 693→	var commitMsg strings.Builder
 694→
 695→	// Subject line is always the checkpoint ID for consistent formatting
 696→	commitMsg.WriteString(fmt.Sprintf("Checkpoint: %s\n\n", opts.CheckpointID))
 697→
 698→	// Include custom description in body if provided (e.g., task checkpoint details)
 699→	if opts.CommitSubject != "" {
 700→		commitMsg.WriteString(opts.CommitSubject + "\n\n")
 701→	}
 702→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.SessionTrailerKey, opts.SessionID))
 703→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy))
 704→	if opts.Agent != "" {
 705→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.AgentTrailerKey, opts.Agent))
 706→	}
 707→	if opts.EphemeralBranch != "" {
 708→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.EphemeralBranchTrailerKey, opts.EphemeralBranch))
 709→	}
 710→	if taskMetadataPath != "" {
 711→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.MetadataTaskTrailerKey, taskMetadataPath))
 712→	}
 713→
 714→	return commitMsg.String()
 715→}
