 735→// ReadCommitted reads a committed checkpoint's summary by ID from the entire/checkpoints/v1 branch.
 736→// Returns only the CheckpointSummary (paths + aggregated stats), not actual content.
 737→// Use ReadSessionContent to read actual transcript/prompts/context.
 738→// Returns nil, nil if the checkpoint doesn't exist.
 739→//
 740→// The storage format uses numbered subdirectories for each session (0-based):
 741→//
 742→//	<checkpoint-id>/
 743→//	├── metadata.json      # CheckpointSummary with sessions map
 744→//	├── 0/                 # First session
 745→//	│   ├── metadata.json  # Session-specific metadata
 746→//	│   └── full.jsonl     # Transcript
 747→//	├── 1/                 # Second session
 748→//	└── ...
 749→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
 750→	_ = ctx // Reserved for future use
 751→
 752→	tree, err := s.getSessionsBranchTree()
 753→	if err != nil {
 754→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
 755→	}
 756→
 757→	checkpointPath := checkpointID.Path()
 758→	checkpointTree, err := tree.Tree(checkpointPath)
 759→	if err != nil {
 760→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
 761→	}
 762→
 763→	// Read root metadata.json as CheckpointSummary
 764→	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
 765→	if err != nil {
 766→		return nil, nil //nolint:nilnil,nilerr // metadata.json not found
 767→	}
 768→
 769→	content, err := metadataFile.Contents()
 770→	if err != nil {
 771→		return nil, fmt.Errorf("failed to read metadata.json: %w", err)
 772→	}
 773→
 774→	var summary CheckpointSummary
 775→	if err := json.Unmarshal([]byte(content), &summary); err != nil {
 776→		return nil, fmt.Errorf("failed to parse metadata.json: %w", err)
 777→	}
 778→
 779→	return &summary, nil
 780→}
