 859→// ReadSessionContentByID reads a session's content by its session ID.
 860→// This is useful when you have the session ID but don't know its index within the checkpoint.
 861→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
 862→// Returns an error if no session with the given ID exists in the checkpoint.
 863→func (s *GitStore) ReadSessionContentByID(ctx context.Context, checkpointID id.CheckpointID, sessionID string) (*SessionContent, error) {
 864→	summary, err := s.ReadCommitted(ctx, checkpointID)
 865→	if err != nil {
 866→		return nil, err
 867→	}
 868→	if summary == nil {
 869→		return nil, ErrCheckpointNotFound
 870→	}
 871→
 872→	// Iterate through sessions to find the one with matching session ID
 873→	for i := range len(summary.Sessions) {
 874→		content, readErr := s.ReadSessionContent(ctx, checkpointID, i)
 875→		if readErr != nil {
 876→			continue
 877→		}
 878→		if content != nil && content.Metadata.SessionID == sessionID {
 879→			return content, nil
 880→		}
 881→	}
 882→
 883→	return nil, fmt.Errorf("session %q not found in checkpoint %s", sessionID, checkpointID)
 884→}
 885→
 886→// ListCommitted lists all committed checkpoints from the entire/checkpoints/v1 branch.
 887→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
 888→//
 889→
 890→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
 891→	_ = ctx // Reserved for future use
 892→
 893→	tree, err := s.getSessionsBranchTree()
 894→	if err != nil {
 895→		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
 896→	}
 897→
 898→	var checkpoints []CommittedInfo
 899→
 900→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
 901→	for _, bucketEntry := range tree.Entries {
 902→		if bucketEntry.Mode != filemode.Dir {
 903→			continue
 904→		}
 905→		// Bucket should be 2 hex chars
 906→		if len(bucketEntry.Name) != 2 {
 907→			continue
 908→		}
 909→
 910→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
 911→		if treeErr != nil {
 912→			continue
 913→		}
 914→
 915→		// Each entry in the bucket is the remaining part of the checkpoint ID
 916→		for _, checkpointEntry := range bucketTree.Entries {
 917→			if checkpointEntry.Mode != filemode.Dir {
 918→				continue
 919→			}
 920→
 921→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
 922→			if cpTreeErr != nil {
 923→				continue
 924→			}
 925→
 926→			// Reconstruct checkpoint ID: <bucket><remaining>
 927→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
 928→			checkpointID, cpIDErr := id.NewCheckpointID(checkpointIDStr)
 929→			if cpIDErr != nil {
 930→				// Skip invalid checkpoint IDs (shouldn't happen with our own data)
 931→				continue
 932→			}
 933→
 934→			info := CommittedInfo{
 935→				CheckpointID: checkpointID,
 936→			}
 937→
 938→			// Get details from root metadata file (CheckpointSummary format)
 939→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
 940→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
 941→					var summary CheckpointSummary
 942→					if err := json.Unmarshal([]byte(content), &summary); err == nil {
 943→						info.CheckpointsCount = summary.CheckpointsCount
 944→						info.FilesTouched = summary.FilesTouched
 945→						info.SessionCount = len(summary.Sessions)
 946→
 947→						// Read session metadata from latest session to get Agent, SessionID, CreatedAt
 948→						if len(summary.Sessions) > 0 {
 949→							latestIndex := len(summary.Sessions) - 1
 950→							latestDir := strconv.Itoa(latestIndex)
 951→							if sessionTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
 952→								if sessionMetadataFile, smErr := sessionTree.File(paths.MetadataFileName); smErr == nil {
 953→									if sessionContent, scErr := sessionMetadataFile.Contents(); scErr == nil {
 954→										var sessionMetadata CommittedMetadata
 955→										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
 956→											info.Agent = sessionMetadata.Agent
 957→											info.SessionID = sessionMetadata.SessionID
 958→											info.CreatedAt = sessionMetadata.CreatedAt
 959→										}
 960→									}
 961→								}
 962→							}
 963→						}
 964→					}
 965→				}
 966→			}
 967→
 968→			checkpoints = append(checkpoints, info)
 969→		}
 970→	}
 971→
 972→	// Sort by time (most recent first)
 973→	sort.Slice(checkpoints, func(i, j int) bool {
 974→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
 975→	})
 976→
 977→	return checkpoints, nil
 978→}
