 993→// GetSessionLog retrieves the session transcript and session ID for a checkpoint.
 994→// This is the primary method for looking up session logs by checkpoint ID.
 995→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
 996→// Returns ErrNoTranscript if the checkpoint exists but has no transcript.
 997→func (s *GitStore) GetSessionLog(cpID id.CheckpointID) ([]byte, string, error) {
 998→	content, err := s.ReadLatestSessionContent(context.Background(), cpID)
 999→	if err != nil {
1000→		if errors.Is(err, ErrCheckpointNotFound) {
1001→			return nil, "", ErrCheckpointNotFound
1002→		}
1003→		return nil, "", fmt.Errorf("failed to read checkpoint: %w", err)
1004→	}
1005→	if len(content.Transcript) == 0 {
1006→		return nil, "", ErrNoTranscript
1007→	}
1008→	return content.Transcript, content.Metadata.SessionID, nil
1009→}
