1016→func LookupSessionLog(cpID id.CheckpointID) ([]byte, string, error) {
1017→	repo, err := git.PlainOpenWithOptions(".", &git.PlainOpenOptions{DetectDotGit: true})
1018→	if err != nil {
1019→		return nil, "", fmt.Errorf("failed to open git repository: %w", err)
1020→	}
1021→	store := NewGitStore(repo)
1022→	return store.GetSessionLog(cpID)
1023→}
