1247→// replaceTranscript writes the full transcript content, replacing any existing transcript.
1248→// Also removes any chunk files from a previous write and updates the content hash.
1249→func (s *GitStore) replaceTranscript(transcript []byte, agentType agent.AgentType, sessionPath string, entries map[string]object.TreeEntry) error {
1250→	// Remove existing transcript files (base + any chunks)
1251→	transcriptBase := sessionPath + paths.TranscriptFileName
1252→	for key := range entries {
1253→		if key == transcriptBase || strings.HasPrefix(key, transcriptBase+".") {
1254→			delete(entries, key)
1255→		}
1256→	}
1257→
1258→	// Chunk the transcript (matches writeTranscript behavior)
1259→	chunks, err := agent.ChunkTranscript(transcript, agentType)
1260→	if err != nil {
1261→		return fmt.Errorf("failed to chunk transcript: %w", err)
1262→	}
1263→
1264→	// Write chunk files
1265→	for i, chunk := range chunks {
1266→		chunkPath := sessionPath + agent.ChunkFileName(paths.TranscriptFileName, i)
1267→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
1268→		if err != nil {
1269→			return fmt.Errorf("failed to create transcript blob: %w", err)
1270→		}
1271→		entries[chunkPath] = object.TreeEntry{
1272→			Name: chunkPath,
1273→			Mode: filemode.Regular,
1274→			Hash: blobHash,
1275→		}
1276→	}
1277→
1278→	// Update content hash
1279→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
1280→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
1281→	if err != nil {
1282→		return fmt.Errorf("failed to create content hash blob: %w", err)
1283→	}
1284→	hashPath := sessionPath + paths.ContentHashFileName
1285→	entries[hashPath] = object.TreeEntry{
1286→		Name: hashPath,
1287→		Mode: filemode.Regular,
1288→		Hash: hashBlob,
1289→	}
1290→
1291→	return nil
1292→}
