1321→// getSessionsBranchTree returns the tree object for the entire/checkpoints/v1 branch.
1322→// Falls back to origin/entire/checkpoints/v1 if the local branch doesn't exist.
1323→func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
1324→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1325→	ref, err := s.repo.Reference(refName, true)
1326→	if err != nil {
