1348→// CreateBlobFromContent creates a blob object from in-memory content.
1349→// Exported for use by strategy package (session_test.go)
1350→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
1351→	obj := repo.Storer.NewEncodedObject()
1352→	obj.SetType(plumbing.BlobObject)
1353→	obj.SetSize(int64(len(content)))
1354→
1355→	writer, err := obj.Writer()
1356→	if err != nil {
1357→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
1358→	}
1359→
1360→	_, err = writer.Write(content)
1361→	if err != nil {
1362→		_ = writer.Close()
1363→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
1364→	}
1365→	if err := writer.Close(); err != nil {
1366→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
1367→	}
1368→
1369→	hash, err := repo.Storer.SetEncodedObject(obj)
1370→	if err != nil {
1371→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
1372→	}
1373→	return hash, nil
1374→}
