1605→// GetCheckpointAuthor retrieves the author of a checkpoint from the entire/checkpoints/v1 commit history.
1606→// Returns the author of the commit that introduced this checkpoint's metadata.json file.
1607→// Returns empty Author if the checkpoint is not found or the sessions branch doesn't exist.
1608→func (s *GitStore) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
1609→	_ = ctx // Reserved for future use
1610→
1611→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1612→	ref, err := s.repo.Reference(refName, true)
1613→	if err != nil {
1614→		return Author{}, nil
1615→	}
1616→
1617→	// Path to the checkpoint's metadata file
1618→	metadataPath := checkpointID.Path() + "/" + paths.MetadataFileName
1619→
1620→	// Walk commit history looking for the commit that introduced this file
1621→	iter, err := s.repo.Log(&git.LogOptions{
1622→		From:  ref.Hash(),
1623→		Order: git.LogOrderCommitterTime,
1624→	})
1625→	if err != nil {
1626→		return Author{}, nil
1627→	}
1628→	defer iter.Close()
1629→
1630→	var author Author
1631→	var foundCommit *object.Commit
1632→
1633→	err = iter.ForEach(func(c *object.Commit) error {
1634→		tree, treeErr := c.Tree()
1635→		if treeErr != nil {
1636→			return nil //nolint:nilerr // Skip commits we can't read, continue searching
1637→		}
1638→
1639→		_, fileErr := tree.File(metadataPath)
1640→		if fileErr != nil {
1641→			// File doesn't exist in this commit - we've gone past the creation point
1642→			if foundCommit != nil {
1643→				return errStopIteration
1644→			}
1645→			return nil
1646→		}
1647→
1648→		// File exists - track it (oldest one with file is the creator)
1649→		foundCommit = c
1650→		author = Author{
1651→			Name:  c.Author.Name,
1652→			Email: c.Author.Email,
1653→		}
1654→		return nil
1655→	})
1656→
1657→	// Ignore errStopIteration - it's just for early exit
1658→	if err != nil && !errors.Is(err, errStopIteration) {
1659→		return Author{}, nil
1660→	}
1661→
1662→	return author, nil
1663→}
