// and were condensed during this PostCommit.

// postCommitActionHandler implements session.ActionHandler for PostCommit.
// Each session in the loop gets its own handler with per-session context.
// Handler methods use the *State parameter from ApplyTransition (same pointer
// as the state being transitioned) rather than capturing state separately.
type postCommitActionHandler struct {
	s                      *ManualCommitStrategy
	logCtx                 context.Context
	repo                   *git.Repository
	checkpointID           id.CheckpointID
	head                   *plumbing.Reference
	commit                 *object.Commit
	newHead                string
	shadowBranchName       string
	shadowBranchesToDelete map[string]struct{}
	committedFileSet       map[string]struct{}
	hasNew                 bool
	filesTouchedBefore     []string

	// Output: set by handler methods, read by caller after TransitionAndLog.
	condensed bool
}

func (h *postCommitActionHandler) HandleCondense(state *session.State) error {
	shouldCondense := h.shouldCondenseWithOverlapCheck(state.Phase.IsActive())

	logging.Debug(h.logCtx, "post-commit: HandleCondense decision",
		slog.String("session_id", state.SessionID),
		slog.String("phase", string(state.Phase)),
		slog.Bool("has_new", h.hasNew),
		slog.Bool("should_condense", shouldCondense),
		slog.String("shadow_branch", h.shadowBranchName),
	)

	if shouldCondense {
		h.condensed = h.s.condenseAndUpdateState(h.logCtx, h.repo, h.checkpointID, state, h.head, h.shadowBranchName, h.shadowBranchesToDelete, h.committedFileSet)
	} else {
		h.s.updateBaseCommitIfChanged(h.logCtx, state, h.newHead)
	}
	return nil
}

func (h *postCommitActionHandler) HandleCondenseIfFilesTouched(state *session.State) error {
	shouldCondense := len(state.FilesTouched) > 0 && h.shouldCondenseWithOverlapCheck(state.Phase.IsActive())

	logging.Debug(h.logCtx, "post-commit: HandleCondenseIfFilesTouched decision",
		slog.String("session_id", state.SessionID),
		slog.String("phase", string(state.Phase)),
		slog.Bool("has_new", h.hasNew),
		slog.Int("files_touched", len(state.FilesTouched)),
		slog.Bool("should_condense", shouldCondense),
		slog.String("shadow_branch", h.shadowBranchName),
	)

	if shouldCondense {
		h.condensed = h.s.condenseAndUpdateState(h.logCtx, h.repo, h.checkpointID, state, h.head, h.shadowBranchName, h.shadowBranchesToDelete, h.committedFileSet)
	} else {
		h.s.updateBaseCommitIfChanged(h.logCtx, state, h.newHead)
	}
	return nil
}

// shouldCondenseWithOverlapCheck returns true if the session should be condensed
// into this commit. Requires both that hasNew is true AND that the session's files
// overlap with the committed files with matching content.
//
// This prevents stale sessions (ACTIVE sessions where the agent was killed, or
// ENDED/IDLE sessions with carry-forward files) from being condensed into every
// unrelated commit.
//
// filesTouchedBefore is populated from:
//   - state.FilesTouched for IDLE/ENDED sessions (set via SaveStep/SaveTaskStep -> mergeFilesTouched)
//   - transcript extraction for ACTIVE sessions when FilesTouched is empty
//
// When filesTouchedBefore is empty:
//   - For ACTIVE sessions: fail-open (trust hasNew) because the agent may be
//     mid-turn before any files are saved to state.
//   - For IDLE/ENDED sessions: return false because there are no files to
//     overlap with the commit.
func (h *postCommitActionHandler) shouldCondenseWithOverlapCheck(isActive bool) bool {
	if !h.hasNew {
		return false
	}
	if len(h.filesTouchedBefore) == 0 {
		return isActive // ACTIVE: fail-open; IDLE/ENDED: no files = no overlap
	}
	// Only check files that were actually changed in this commit.
	// Without this, files that exist in the tree but weren't changed
	// would pass the "modified file" check in filesOverlapWithContent
	// (because the file exists in the parent tree), causing stale
	// sessions to be incorrectly condensed.
	var committedTouchedFiles []string
	for _, f := range h.filesTouchedBefore {
		if _, ok := h.committedFileSet[f]; ok {
			committedTouchedFiles = append(committedTouchedFiles, f)
		}
	}
	if len(committedTouchedFiles) == 0 {
		return false
	}
	return filesOverlapWithContent(h.repo, h.shadowBranchName, h.commit, committedTouchedFiles)
}

func (h *postCommitActionHandler) HandleDiscardIfNoFiles(state *session.State) error {
	if len(state.FilesTouched) == 0 {
		logging.Debug(h.logCtx, "post-commit: skipping empty ended session (no files to condense)",
			slog.String("session_id", state.SessionID),
		)
	}
	h.s.updateBaseCommitIfChanged(h.logCtx, state, h.newHead)
	return nil
}

func (h *postCommitActionHandler) HandleWarnStaleSession(_ *session.State) error {
	// Not produced by EventGitCommit; no-op for exhaustiveness.
	return nil
}

// During rebase/cherry-pick/revert operations, phase transitions are skipped entirely.

	return nil
}

// During rebase/cherry-pick/revert operations, phase transitions are skipped entirely.
//

func (s *ManualCommitStrategy) PostCommit() error {
	logCtx := logging.WithComponent(context.Background(), "checkpoint")

	repo, err := OpenRepository()
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	// Get HEAD commit to check for trailer
	head, err := repo.Head()
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	commit, err := repo.CommitObject(head.Hash())
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	// Check if commit has checkpoint trailer (ParseCheckpoint validates format)
	checkpointID, found := trailers.ParseCheckpoint(commit.Message)
	if !found {
		// No trailer — user removed it or it was never added (mid-turn commit).
		// Still update BaseCommit for active sessions so future commits can match.
		s.postCommitUpdateBaseCommitOnly(logCtx, head)
		return nil
	}

	worktreePath, err := paths.WorktreeRoot()
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	// Find all active sessions for this worktree
	sessions, err := s.findSessionsForWorktree(worktreePath)
	if err != nil || len(sessions) == 0 {
		logging.Warn(logCtx, "post-commit: no active sessions despite trailer",
			slog.String("strategy", "manual-commit"),
			slog.String("checkpoint_id", checkpointID.String()),
		)
		return nil //nolint:nilerr // Intentional: hooks must be silent on failure
	}

	// Build transition context
	isRebase := isGitSequenceOperation()
	transitionCtx := session.TransitionContext{
		IsRebaseInProgress: isRebase,
	}

	if isRebase {
		logging.Debug(logCtx, "post-commit: rebase/sequence in progress, skipping phase transitions",
			slog.String("strategy", "manual-commit"),
		)
	}

	// Track shadow branch names and whether they can be deleted
	shadowBranchesToDelete := make(map[string]struct{})
	// Track active sessions that were NOT condensed — their shadow branches must be preserved
	uncondensedActiveOnBranch := make(map[string]bool)

	newHead := head.Hash().String()
	committedFileSet := filesChangedInCommit(commit)

	for _, state := range sessions {
		shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)

		// Check for new content (needed for TransitionContext and condensation).
		// Fail-open: if content check errors, assume new content exists so we
		// don't silently skip data that should have been condensed.
		//
		// For ACTIVE sessions: the commit has a checkpoint trailer (verified above),
		// meaning PrepareCommitMsg already determined this commit is session-related.
		// The trailer is only added when either:
		//   - No TTY (agent/subagent committing) — added unconditionally
		//   - TTY (human committing) — added after content detection confirmed agent work
		// In both cases, PrepareCommitMsg already validated this commit. We trust
		// that decision here. Transcript-based re-validation is unreliable because
		// subagent transcripts may not be available yet (subagent still running).
		var hasNew bool
		if state.Phase.IsActive() {
			hasNew = true
		} else {
			var contentErr error
			hasNew, contentErr = s.sessionHasNewContent(repo, state)
			if contentErr != nil {
				hasNew = true
				logging.Debug(logCtx, "post-commit: error checking session content, assuming new content",
					slog.String("session_id", state.SessionID),
					slog.String("error", contentErr.Error()),
				)
			}
		}
		transitionCtx.HasFilesTouched = len(state.FilesTouched) > 0

		// Save FilesTouched BEFORE TransitionAndLog — the handler's condensation
		// clears it, but we need the original list for carry-forward computation.
		// For mid-session commits (ACTIVE, no shadow branch), state.FilesTouched may be empty
		// because no SaveStep/Stop has been called yet. Extract files from transcript.
		filesTouchedBefore := make([]string, len(state.FilesTouched))
		copy(filesTouchedBefore, state.FilesTouched)
		if len(filesTouchedBefore) == 0 && state.Phase.IsActive() && state.TranscriptPath != "" {
			filesTouchedBefore = s.extractFilesFromLiveTranscript(state)
		}

		logging.Debug(logCtx, "post-commit: carry-forward prep",
			slog.String("session_id", state.SessionID),
			slog.Bool("is_active", state.Phase.IsActive()),
			slog.String("transcript_path", state.TranscriptPath),
			slog.Int("files_touched_before", len(filesTouchedBefore)),
			slog.Any("files", filesTouchedBefore),
		)

		// Run the state machine transition with handler for strategy-specific actions.
		handler := &postCommitActionHandler{
			s:                      s,
			logCtx:                 logCtx,
			repo:                   repo,
			checkpointID:           checkpointID,
			head:                   head,
			commit:                 commit,
			newHead:                newHead,
			shadowBranchName:       shadowBranchName,
			shadowBranchesToDelete: shadowBranchesToDelete,
			committedFileSet:       committedFileSet,
			hasNew:                 hasNew,
			filesTouchedBefore:     filesTouchedBefore,
		}

		if err := TransitionAndLog(state, session.EventGitCommit, transitionCtx, handler); err != nil {
			fmt.Fprintf(os.Stderr, "[entire] Warning: post-commit action handler error: %v\n", err)
		}

		// Record checkpoint ID for ACTIVE sessions so HandleTurnEnd can finalize
		// with full transcript. IDLE/ENDED sessions already have complete transcripts.
		// NOTE: This check runs AFTER TransitionAndLog updated the phase. It relies on
		// ACTIVE + GitCommit → ACTIVE (phase stays ACTIVE). If that state machine
		// transition ever changed, this guard would silently stop recording IDs.
		if handler.condensed && state.Phase.IsActive() {
			state.TurnCheckpointIDs = append(state.TurnCheckpointIDs, checkpointID.String())
		}

		// Carry forward remaining uncommitted files so the next commit gets its
		// own checkpoint ID. This applies to ALL phases — if a user splits their
		// commit across two `git commit` invocations, each gets a 1:1 checkpoint.
		// Uses content-aware comparison: if user did `git add -p` and committed
		// partial changes, the file still has remaining agent changes to carry forward.
		if handler.condensed {
			remainingFiles := filesWithRemainingAgentChanges(repo, shadowBranchName, commit, filesTouchedBefore, committedFileSet)
			state.FilesTouched = remainingFiles
			logging.Debug(logCtx, "post-commit: carry-forward decision (content-aware)",
				slog.String("session_id", state.SessionID),
				slog.Int("files_touched_before", len(filesTouchedBefore)),
				slog.Int("committed_files", len(committedFileSet)),
				slog.Int("remaining_files", len(remainingFiles)),
				slog.Any("remaining", remainingFiles),
				slog.Any("committed_files", committedFileSet),
			)
			if len(remainingFiles) > 0 {
				s.carryForwardToNewShadowBranch(logCtx, repo, state, remainingFiles)
			}
		}

		// Save the updated state
		if err := s.saveSessionState(state); err != nil {
			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to update session state: %v\n", err)
		}

		// Only preserve shadow branch for active sessions that were NOT condensed.
		// Condensed sessions already have their data on entire/checkpoints/v1.
		if state.Phase.IsActive() && !handler.condensed {
			uncondensedActiveOnBranch[shadowBranchName] = true
		}
	}

	// Clean up shadow branches — only delete when ALL sessions on the branch are non-active
	// or were condensed during this PostCommit.
	for shadowBranchName := range shadowBranchesToDelete {
		if uncondensedActiveOnBranch[shadowBranchName] {
			logging.Debug(logCtx, "post-commit: preserving shadow branch (active session exists)",
				slog.String("shadow_branch", shadowBranchName),
			)
			continue
		}
		if err := deleteShadowBranch(repo, shadowBranchName); err != nil {
			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to clean up %s: %v\n", shadowBranchName, err)
		} else {
			fmt.Fprintf(os.Stderr, "[entire] Cleaned up shadow branch: %s\n", shadowBranchName)
			logging.Info(logCtx, "shadow branch deleted",
				slog.String("strategy", "manual-commit"),
				slog.String("shadow_branch", shadowBranchName),
			)
		}
	}

	return nil
}

// condenseAndUpdateState runs condensation for a session and updates state afterward.
// Returns true if condensation succeeded.
func (s *ManualCommitStrategy) condenseAndUpdateState(
	logCtx context.Context,
	repo *git.Repository,
	checkpointID id.CheckpointID,
	state *SessionState,

// condenseAndUpdateState runs condensation for a session and updates state afterward.
// Returns true if condensation succeeded.
func (s *ManualCommitStrategy) condenseAndUpdateState(
	logCtx context.Context,
	repo *git.Repository,
	checkpointID id.CheckpointID,
	state *SessionState,
	head *plumbing.Reference,
	shadowBranchName string,
	shadowBranchesToDelete map[string]struct{},
	committedFiles map[string]struct{},
) bool {
	result, err := s.CondenseSession(repo, checkpointID, state, committedFiles)
	if err != nil {
		fmt.Fprintf(os.Stderr, "[entire] Warning: condensation failed for session %s: %v\n",
			state.SessionID, err)
		logging.Warn(logCtx, "post-commit: condensation failed",
			slog.String("session_id", state.SessionID),
			slog.String("error", err.Error()),
		)
		return false
	}

	// Track this shadow branch for cleanup
	shadowBranchesToDelete[shadowBranchName] = struct{}{}

	// Update session state for the new base commit
	newHead := head.Hash().String()
	state.BaseCommit = newHead
	state.AttributionBaseCommit = newHead
	state.StepCount = 0
	state.CheckpointTranscriptStart = result.TotalTranscriptLines

	// Clear attribution tracking — condensation already used these values
	state.PromptAttributions = nil
	state.PendingPromptAttribution = nil
	state.FilesTouched = nil

	// Save checkpoint ID so subsequent commits can reuse it (e.g., amend restores trailer)
	state.LastCheckpointID = checkpointID

	shortID := state.SessionID
	if len(shortID) > 8 {
		shortID = shortID[:8]
	}
	fmt.Fprintf(os.Stderr, "[entire] Condensed session %s: %s (%d checkpoints)\n",
		shortID, result.CheckpointID, result.CheckpointsCount)

	logging.Info(logCtx, "session condensed",
		slog.String("strategy", "manual-commit"),
		slog.String("checkpoint_id", result.CheckpointID.String()),
		slog.Int("checkpoints_condensed", result.CheckpointsCount),
		slog.Int("transcript_lines", result.TotalTranscriptLines),
	)

	return true
}

// updateBaseCommitIfChanged updates BaseCommit to newHead if it changed.
// Only updates ACTIVE sessions. IDLE/ENDED sessions should NOT have their
// BaseCommit updated, as this would cause them to be incorrectly associated
// with a new shadow branch and potentially condensed on future commits.
func (s *ManualCommitStrategy) updateBaseCommitIfChanged(logCtx context.Context, state *SessionState, newHead string) {
	// Only update ACTIVE sessions. IDLE/ENDED sessions are kept around for
	// LastCheckpointID reuse and should not be advanced to HEAD.
	if !state.Phase.IsActive() {
		logging.Debug(logCtx, "post-commit: updateBaseCommitIfChanged skipped non-active session",
			slog.String("session_id", state.SessionID),
			slog.String("phase", string(state.Phase)),
		)
		return
	}
	if state.BaseCommit != newHead {
		state.BaseCommit = newHead
		logging.Debug(logCtx, "post-commit: updated BaseCommit",
			slog.String("session_id", state.SessionID),
			slog.String("new_head", truncateHash(newHead)),
		)
	}
}

package strategy

import (
	"context"
	"io"
	"log/slog"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/object"
)

// Content-aware overlap detection for checkpoint management.
//
// These functions determine whether a commit contains session-related work by comparing
// file content (not just filenames) against the shadow branch. This enables accurate
// detection of the "reverted and replaced" scenario where a user:
// 1. Reverts session changes (e.g., git checkout -- file.txt)
// 2. Creates completely different content in the same file
// 3. Commits the new content
//
// In this scenario, the commit should NOT get a checkpoint trailer because the
// session's work was discarded, not incorporated.
//
// The key distinction:
// - Modified files (exist in parent commit): Always count as overlap, regardless of
//   content changes. The user is editing session's work.
// - New files (don't exist in parent): Require content match against shadow branch.
//   If content differs completely, the session's work was likely reverted & replaced.

// filesOverlapWithContent checks if any file in filesTouched overlaps with the committed
// content, using content-aware comparison to detect the "reverted and replaced" scenario.
//
// This is used in PostCommit to determine if a session has work in the commit.
func filesOverlapWithContent(repo *git.Repository, shadowBranchName string, headCommit *object.Commit, filesTouched []string) bool {
	logCtx := logging.WithComponent(context.Background(), "checkpoint")

	// Build set of filesTouched for quick lookup
	touchedSet := make(map[string]bool)
	for _, f := range filesTouched {
		touchedSet[f] = true
	}

	// Get HEAD commit tree (the committed content)
	headTree, err := headCommit.Tree()
	if err != nil {
		logging.Debug(logCtx, "filesOverlapWithContent: failed to get HEAD tree, falling back to filename check",
			slog.String("error", err.Error()),
		)
		return len(filesTouched) > 0 // Fall back: assume overlap if any files touched
	}

	// Get shadow branch tree (the session's content)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	shadowRef, err := repo.Reference(refName, true)
	if err != nil {
		logging.Debug(logCtx, "filesOverlapWithContent: shadow branch not found, falling back to filename check",
			slog.String("branch", shadowBranchName),
			slog.String("error", err.Error()),
		)
		return len(filesTouched) > 0 // Fall back: assume overlap if any files touched
	}

	shadowCommit, err := repo.CommitObject(shadowRef.Hash())
	if err != nil {
		logging.Debug(logCtx, "filesOverlapWithContent: failed to get shadow commit, falling back to filename check",
			slog.String("error", err.Error()),
		)
		return len(filesTouched) > 0
	}

	shadowTree, err := shadowCommit.Tree()
	if err != nil {
		logging.Debug(logCtx, "filesOverlapWithContent: failed to get shadow tree, falling back to filename check",
			slog.String("error", err.Error()),
		)
		return len(filesTouched) > 0
	}

	// Get the parent commit tree to determine if files are modified vs newly created.
	// For modified files (exist in parent), we count as overlap regardless of content
	// because the user is editing the session's work.
	// For newly created files (don't exist in parent), we check content to detect
	// the "reverted and replaced" scenario where user deleted session's work and
	// created something completely different.
	var parentTree *object.Tree
	if headCommit.NumParents() > 0 {
		if parent, err := headCommit.Parent(0); err == nil {
			if pTree, err := parent.Tree(); err == nil {
				parentTree = pTree
			}
		}
	}

	// Check each file in filesTouched
	for _, filePath := range filesTouched {
		// Get file from HEAD tree (the committed content)
		headFile, err := headTree.File(filePath)
		if err != nil {
			// File not in HEAD commit. Check if this is a deletion (existed in parent).
			// Deletions count as overlap because the agent's action (deleting the file)
			// is being committed - we want the session context linked to this commit.
			if parentTree != nil {
				if _, parentErr := parentTree.File(filePath); parentErr == nil {
					// File existed in parent but not in HEAD - this is a deletion
					logging.Debug(logCtx, "filesOverlapWithContent: deleted file counts as overlap",
						slog.String("file", filePath),
					)
					return true
				}
			}
			// File didn't exist in parent either - not a deletion, skip
			continue
		}

		// Check if this is a modified file (exists in parent) or new file
		isModified := false
		if parentTree != nil {
			if _, err := parentTree.File(filePath); err == nil {
				isModified = true
			}
		}

		// Modified files always count as overlap (user edited session's work)
		if isModified {
			logging.Debug(logCtx, "filesOverlapWithContent: modified file counts as overlap",
				slog.String("file", filePath),
			)
			return true
		}

		// For new files, check content against shadow branch
		shadowFile, err := shadowTree.File(filePath)
		if err != nil {
			// File not in shadow branch - this shouldn't happen but skip it
			logging.Debug(logCtx, "filesOverlapWithContent: file in filesTouched but not in shadow branch",
				slog.String("file", filePath),
			)
			continue
		}

		// Compare by hash (blob hash) - exact content match required for new files
		if headFile.Hash == shadowFile.Hash {
			logging.Debug(logCtx, "filesOverlapWithContent: new file content match found",
				slog.String("file", filePath),
				slog.String("hash", headFile.Hash.String()),
			)
			return true
		}

		logging.Debug(logCtx, "filesOverlapWithContent: new file content mismatch (may be reverted & replaced)",
			slog.String("file", filePath),
			slog.String("head_hash", headFile.Hash.String()),
			slog.String("shadow_hash", shadowFile.Hash.String()),
		)
	}

	logging.Debug(logCtx, "filesOverlapWithContent: no overlapping files found",
		slog.Int("files_checked", len(filesTouched)),
	)
	return false
}

// stagedFilesOverlapWithContent checks if any staged file overlaps with filesTouched,
// distinguishing between modified files (always overlap) and new files (check content).
//
// For modified files (already exist in HEAD), we count as overlap because the user
// is editing the session's work. For new files (don't exist in HEAD), we require
// content match to detect the "reverted and replaced" scenario.
//
// This is used in PrepareCommitMsg for carry-forward scenarios.
func stagedFilesOverlapWithContent(repo *git.Repository, shadowTree *object.Tree, stagedFiles, filesTouched []string) bool {
	logCtx := logging.WithComponent(context.Background(), "checkpoint")

	// Build set of filesTouched for quick lookup
	touchedSet := make(map[string]bool)
	for _, f := range filesTouched {
		touchedSet[f] = true
	}

	}
	return false
}

// filesWithRemainingAgentChanges returns files from filesTouched that still have
// uncommitted agent changes. This is used for carry-forward after partial commits.
//
// A file has remaining agent changes if:
//   - It wasn't committed at all (not in committedFiles), OR
//   - It was committed but the committed content doesn't match the shadow branch
//     (user committed partial changes, e.g., via git add -p)
//
// Falls back to file-level subtraction if shadow branch is unavailable.
func filesWithRemainingAgentChanges(
	repo *git.Repository,
	shadowBranchName string,
	headCommit *object.Commit,
	filesTouched []string,
	committedFiles map[string]struct{},
) []string {
	logCtx := logging.WithComponent(context.Background(), "checkpoint")

	// Get HEAD commit tree (the committed content)
	commitTree, err := headCommit.Tree()
	if err != nil {
		logging.Debug(logCtx, "filesWithRemainingAgentChanges: failed to get commit tree, falling back to file subtraction",
			slog.String("error", err.Error()),
		)
		return subtractFilesByName(filesTouched, committedFiles)
	}

	// Get shadow branch tree (the session's full content)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	shadowRef, err := repo.Reference(refName, true)
	if err != nil {
		logging.Debug(logCtx, "filesWithRemainingAgentChanges: shadow branch not found, falling back to file subtraction",
			slog.String("branch", shadowBranchName),
			slog.String("error", err.Error()),
		)
		return subtractFilesByName(filesTouched, committedFiles)
	}

	shadowCommit, err := repo.CommitObject(shadowRef.Hash())
	if err != nil {
		logging.Debug(logCtx, "filesWithRemainingAgentChanges: failed to get shadow commit, falling back to file subtraction",
			slog.String("error", err.Error()),
		)
		return subtractFilesByName(filesTouched, committedFiles)
	}

	shadowTree, err := shadowCommit.Tree()
	if err != nil {
		logging.Debug(logCtx, "filesWithRemainingAgentChanges: failed to get shadow tree, falling back to file subtraction",
			slog.String("error", err.Error()),
		)
		return subtractFilesByName(filesTouched, committedFiles)
	}

	var remaining []string

	for _, filePath := range filesTouched {
		// If file wasn't committed at all, it definitely has remaining changes
		if _, wasCommitted := committedFiles[filePath]; !wasCommitted {
			remaining = append(remaining, filePath)
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: file not committed, keeping",
				slog.String("file", filePath),
			)
			continue
		}

		// File was committed - check if committed content matches shadow branch
		shadowFile, err := shadowTree.File(filePath)
		if err != nil {
			// File not in shadow branch - nothing to carry forward for this file
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: file not in shadow branch, skipping",
				slog.String("file", filePath),
			)
			continue
		}

		commitFile, err := commitTree.File(filePath)
		if err != nil {
			// File not in commit tree (deleted?) - keep it if it's in shadow
			remaining = append(remaining, filePath)
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: file not in commit tree but in shadow, keeping",
				slog.String("file", filePath),
			)
			continue
		}

		// Compare hashes - if different, there are still uncommitted agent changes
		if commitFile.Hash != shadowFile.Hash {
			remaining = append(remaining, filePath)
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: content mismatch, keeping for carry-forward",
				slog.String("file", filePath),
				slog.String("commit_hash", commitFile.Hash.String()[:7]),
				slog.String("shadow_hash", shadowFile.Hash.String()[:7]),
			)
		} else {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: content fully committed",
				slog.String("file", filePath),
			)
		}
	}

	logging.Debug(logCtx, "filesWithRemainingAgentChanges: result",
		slog.Int("files_touched", len(filesTouched)),
		slog.Int("committed_files", len(committedFiles)),
		slog.Int("remaining_files", len(remaining)),
	)

	return remaining
}

// subtractFilesByName returns files from filesTouched that are NOT in committedFiles.
// This is a fallback when content-aware comparison isn't possible.
func subtractFilesByName(filesTouched []string, committedFiles map[string]struct{}) []string {
	logCtx := logging.WithComponent(context.Background(), "checkpoint")
	logging.Debug(logCtx, "subtractFilesByName: ",
		slog.Any("filesTouched", filesTouched),

	}
	if len(content.Transcript) == 0 {
		return nil, fmt.Errorf("no transcript found for checkpoint: %s", checkpointID)
	}

	return content.Transcript, nil
}

// CondenseSession condenses a session's shadow branch to permanent storage.
// checkpointID is the 12-hex-char value from the Entire-Checkpoint trailer.
// Metadata is stored at sharded path: <checkpoint_id[:2]>/<checkpoint_id[2:]>/
// Uses checkpoint.GitStore.WriteCommitted for the git operations.
//
// For mid-session commits (no Stop/SaveStep called yet), the shadow branch may not exist.
// In this case, data is extracted from the live transcript instead.
func (s *ManualCommitStrategy) CondenseSession(repo *git.Repository, checkpointID id.CheckpointID, state *SessionState, committedFiles map[string]struct{}) (*CondenseResult, error) {
	// Get shadow branch (may not exist for mid-session commits)
	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	ref, err := repo.Reference(refName, true)
	hasShadowBranch := err == nil

	var sessionData *ExtractedSessionData
	if hasShadowBranch {
		// Extract session data from the shadow branch (with live transcript fallback).
		// Use tracked files from session state instead of collecting all files from tree.
		// Pass agent type to handle different transcript formats (JSONL for Claude, JSON for Gemini).
		// Pass live transcript path so condensation reads the current file rather than a
		// potentially stale shadow branch copy (SaveStep may have been skipped if the
		// last turn had no code changes).
		// Pass CheckpointTranscriptStart for accurate token calculation (line offset for Claude, message index for Gemini).
		sessionData, err = s.extractSessionData(repo, ref.Hash(), state.SessionID, state.FilesTouched, state.AgentType, state.TranscriptPath, state.CheckpointTranscriptStart, state.Phase.IsActive())
		if err != nil {
			return nil, fmt.Errorf("failed to extract session data: %w", err)
		}
	} else {
		// No shadow branch: mid-session commit before Stop/SaveStep.
		// Extract data directly from live transcript.
		if state.TranscriptPath == "" {
			return nil, errors.New("shadow branch not found and no live transcript available")
		}
		// Ensure transcript file exists (OpenCode creates it lazily via `opencode export`).
		// Only wait for flush when the session is active — for idle/ended sessions the
		// transcript is already fully flushed (the Stop hook completed the flush).
		if state.Phase.IsActive() {
			prepareTranscriptIfNeeded(state.AgentType, state.TranscriptPath)
		}
		sessionData, err = s.extractSessionDataFromLiveTranscript(state)
		if err != nil {
			return nil, fmt.Errorf("failed to extract session data from live transcript: %w", err)
		}
	}

	// For 1:1 checkpoint model: filter files_touched to only include files actually
	// committed in this specific commit. This ensures each checkpoint represents
	// exactly the files in that commit, not all files mentioned in the transcript.
	if len(committedFiles) > 0 {
		// Track if we had files before filtering to distinguish between:
		// - Session had files but none were committed (don't fallback)
		// - Session had no files to begin with (mid-session commit, fallback OK)
		hadFilesBeforeFiltering := len(sessionData.FilesTouched) > 0

		if hadFilesBeforeFiltering {
			// Filter to intersection of transcript-extracted files and committed files
			filtered := make([]string, 0, len(sessionData.FilesTouched))
			for _, f := range sessionData.FilesTouched {
				if _, ok := committedFiles[f]; ok {
					filtered = append(filtered, f)
				}
			}
			sessionData.FilesTouched = filtered
		}

		// Only use committedFiles as fallback for genuine mid-session commits where
		// no files were tracked yet (extraction returned empty). Do NOT fallback when
		// the session had files that simply didn't overlap with the commit - that
		// indicates an unrelated session that shouldn't have its files_touched
		// overwritten with unrelated committed files.
		if len(sessionData.FilesTouched) == 0 && !hadFilesBeforeFiltering {
			sessionData.FilesTouched = make([]string, 0, len(committedFiles))
			for f := range committedFiles {
				sessionData.FilesTouched = append(sessionData.FilesTouched, f)
			}
		}
	}

	// Get checkpoint store
	store, err := s.getCheckpointStore()
	if err != nil {
		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
	}

	// Get author info
	authorName, authorEmail := GetGitAuthorFromRepo(repo)
	// Calculate attribution. When no shadow branch exists (agent committed mid-turn
	// before SaveStep), pass nil ref — the function uses HEAD as the shadow tree
	// since the agent's commit IS HEAD (no user edits between agent work and commit).
	attribution := calculateSessionAttributions(repo, ref, sessionData, state)
	// Get current branch name
	branchName := GetCurrentBranchName(repo)

	// Generate summary if enabled
	var summary *cpkg.Summary
	if settings.IsSummarizeEnabled() && len(sessionData.Transcript) > 0 {
		logCtx := logging.WithComponent(context.Background(), "attribution")
		summarizeCtx := logging.WithComponent(logCtx, "summarize")

		// Scope transcript to this checkpoint's portion.
		// For Claude Code (JSONL), CheckpointTranscriptStart is a line offset.
		// For Gemini/OpenCode (JSON), CheckpointTranscriptStart is a message index.
		var scopedTranscript []byte
		switch state.AgentType {
		case agent.AgentTypeGemini:
			scoped, sliceErr := geminicli.SliceFromMessage(sessionData.Transcript, state.CheckpointTranscriptStart)
			if sliceErr != nil {
				logging.Warn(summarizeCtx, "failed to scope Gemini transcript for summary",
					slog.String("session_id", state.SessionID),
					slog.String("error", sliceErr.Error()))
			}
			scopedTranscript = scoped
		case agent.AgentTypeOpenCode:
			scoped, sliceErr := opencode.SliceFromMessage(sessionData.Transcript, state.CheckpointTranscriptStart)
			if sliceErr != nil {
				logging.Warn(summarizeCtx, "failed to scope OpenCode transcript for summary",
					slog.String("session_id", state.SessionID),
					slog.String("error", sliceErr.Error()))
			}
			scopedTranscript = scoped
		case agent.AgentTypeClaudeCode, agent.AgentTypeCursor, agent.AgentTypeUnknown:
			scopedTranscript = transcript.SliceFromLine(sessionData.Transcript, state.CheckpointTranscriptStart)
		}
		if len(scopedTranscript) > 0 {
			var err error
			summary, err = summarize.GenerateFromTranscript(summarizeCtx, scopedTranscript, sessionData.FilesTouched, state.AgentType, nil)
			if err != nil {
				logging.Warn(summarizeCtx, "summary generation failed",
					slog.String("session_id", state.SessionID),
					slog.String("error", err.Error()))
				// Continue without summary - non-blocking
			} else {
				logging.Info(summarizeCtx, "summary generated",
					slog.String("session_id", state.SessionID))
			}
		}
	}

	// Write checkpoint metadata using the checkpoint store
	if err := store.WriteCommitted(context.Background(), cpkg.WriteCommittedOptions{
		CheckpointID:                checkpointID,
		SessionID:                   state.SessionID,
		Strategy:                    StrategyNameManualCommit,
		Branch:                      branchName,
		Transcript:                  sessionData.Transcript,
		Prompts:                     sessionData.Prompts,
		Context:                     sessionData.Context,
		FilesTouched:                sessionData.FilesTouched,
		CheckpointsCount:            state.StepCount,
		EphemeralBranch:             shadowBranchName,
		AuthorName:                  authorName,
		AuthorEmail:                 authorEmail,
		Agent:                       state.AgentType,
		TurnID:                      state.TurnID,
		TranscriptIdentifierAtStart: state.TranscriptIdentifierAtStart,
		CheckpointTranscriptStart:   state.CheckpointTranscriptStart,
		TokenUsage:                  sessionData.TokenUsage,
		InitialAttribution:          attribution,
		Summary:                     summary,
	}); err != nil {
		return nil, fmt.Errorf("failed to write checkpoint metadata: %w", err)
	}

	return &CondenseResult{
		CheckpointID:         checkpointID,
		SessionID:            state.SessionID,
		CheckpointsCount:     state.StepCount,
		FilesTouched:         sessionData.FilesTouched,
		TotalTranscriptLines: sessionData.FullTranscriptLines,
	}, nil
}

func calculateSessionAttributions(repo *git.Repository, shadowRef *plumbing.Reference, sessionData *ExtractedSessionData, state *SessionState) *cpkg.InitialAttribution {
	// Calculate initial attribution using accumulated prompt attribution data.
	// This uses user edits captured at each prompt start (before agent works),
	// plus any user edits after the final checkpoint (shadow → head).
	//
	// When shadowRef is nil (agent committed mid-turn before SaveStep),
	// HEAD is used as the shadow tree. This is correct because the agent's
	// commit IS HEAD — there are no user edits between agent work and commit.
	logCtx := logging.WithComponent(context.Background(), "attribution")

	headRef, headErr := repo.Head()
	if headErr != nil {
		logging.Debug(logCtx, "attribution skipped: failed to get HEAD",
			slog.String("error", headErr.Error()))
		return nil
	}

	headCommit, commitErr := repo.CommitObject(headRef.Hash())
	if commitErr != nil {
		logging.Debug(logCtx, "attribution skipped: failed to get HEAD commit",

	headCommit, commitErr := repo.CommitObject(headRef.Hash())
	if commitErr != nil {
		logging.Debug(logCtx, "attribution skipped: failed to get HEAD commit",
			slog.String("error", commitErr.Error()))
		return nil
	}

	headTree, treeErr := headCommit.Tree()
	if treeErr != nil {
		logging.Debug(logCtx, "attribution skipped: failed to get HEAD tree",
			slog.String("error", treeErr.Error()))
		return nil
	}

	// Get shadow tree: from shadow branch if available, otherwise HEAD (agent committed directly).
	var shadowTree *object.Tree
	if shadowRef != nil {
		shadowCommit, shadowErr := repo.CommitObject(shadowRef.Hash())
		if shadowErr != nil {
			logging.Debug(logCtx, "attribution skipped: failed to get shadow commit",
				slog.String("error", shadowErr.Error()),
				slog.String("shadow_ref", shadowRef.Hash().String()))
			return nil
		}
		var shadowTreeErr error
		shadowTree, shadowTreeErr = shadowCommit.Tree()
		if shadowTreeErr != nil {
			logging.Debug(logCtx, "attribution skipped: failed to get shadow tree",
				slog.String("error", shadowTreeErr.Error()))
			return nil
		}
	} else {
		// No shadow branch: agent committed mid-turn. Use HEAD as shadow
		// because the agent's work is the commit itself.
		logging.Debug(logCtx, "attribution: using HEAD as shadow (no shadow branch)")
		shadowTree = headTree
	}

	// Get base tree (state before session started)
	var baseTree *object.Tree
	attrBase := state.AttributionBaseCommit
	if attrBase == "" {
		attrBase = state.BaseCommit // backward compat
	}
	if baseCommit, baseErr := repo.CommitObject(plumbing.NewHash(attrBase)); baseErr == nil {
		if tree, baseTErr := baseCommit.Tree(); baseTErr == nil {
			baseTree = tree
		} else {
			logging.Debug(logCtx, "attribution: base tree unavailable",
				slog.String("error", baseTErr.Error()))
		}
	} else {
		logging.Debug(logCtx, "attribution: base commit unavailable",
			slog.String("error", baseErr.Error()),
			slog.String("attribution_base", attrBase))
	}

	// Log accumulated prompt attributions for debugging
	var totalUserAdded, totalUserRemoved int
	for i, pa := range state.PromptAttributions {
		totalUserAdded += pa.UserLinesAdded
		totalUserRemoved += pa.UserLinesRemoved
		logging.Debug(logCtx, "prompt attribution data",
			slog.Int("checkpoint", pa.CheckpointNumber),
			slog.Int("user_added", pa.UserLinesAdded),
			slog.Int("user_removed", pa.UserLinesRemoved),
			slog.Int("agent_added", pa.AgentLinesAdded),
			slog.Int("agent_removed", pa.AgentLinesRemoved),
			slog.Int("index", i))
	}

	attribution := CalculateAttributionWithAccumulated(
		baseTree,
		shadowTree,
		headTree,
		sessionData.FilesTouched,
		state.PromptAttributions,
	)

	if attribution != nil {
		logging.Info(logCtx, "attribution calculated",
			slog.Int("agent_lines", attribution.AgentLines),
			slog.Int("human_added", attribution.HumanAdded),
			slog.Int("human_modified", attribution.HumanModified),
			slog.Int("human_removed", attribution.HumanRemoved),
			slog.Int("total_committed", attribution.TotalCommitted),
			slog.Float64("agent_percentage", attribution.AgentPercentage),
			slog.Int("accumulated_user_added", totalUserAdded),
			slog.Int("accumulated_user_removed", totalUserRemoved),
			slog.Int("files_touched", len(sessionData.FilesTouched)))
	}

	return attribution
}

