 11→func TestCalculateTokenUsage_CursorReturnsNil(t *testing.T) {
 12→	t.Parallel()
 13→
 14→	// Cursor transcripts don't contain token usage data, so calculateTokenUsage
 15→	// should return nil (not an empty struct) to signal "no data available".
 16→	transcript := []byte(`{"role":"user","message":{"content":[{"type":"text","text":"hello"}]}}`)
 17→
 18→	result := calculateTokenUsage(agent.AgentTypeCursor, transcript, 0)
 19→	if result != nil {
