 42→		`{"type":"assistant","uuid":"u2","message":{"id":"msg_001","usage":{"input_tokens":10,"output_tokens":5}}}`,
 43→	}
 44→	data := []byte(strings.Join(lines, "\n") + "\n")
 45→
 46→	result := calculateTokenUsage(agent.AgentTypeClaudeCode, data, 0)
 47→	if result == nil {
 48→		t.Fatal("calculateTokenUsage(ClaudeCode) = nil, want non-nil")
 49→	}
