 58→func TestCalculateTokenUsage_ClaudeCodeWithOffset(t *testing.T) {
 59→	t.Parallel()
 60→
 61→	// 4-line transcript; start at offset 2 to only count the second pair
 62→	lines := []string{
 63→		`{"type":"human","uuid":"u1","message":{"content":"first"}}`,
 64→		`{"type":"assistant","uuid":"u2","message":{"id":"msg_001","usage":{"input_tokens":10,"output_tokens":5}}}`,
 65→		`{"type":"human","uuid":"u3","message":{"content":"second"}}`,
 66→		`{"type":"assistant","uuid":"u4","message":{"id":"msg_002","usage":{"input_tokens":20,"output_tokens":15}}}`,
 67→	}
 68→	data := []byte(strings.Join(lines, "\n") + "\n")
 69→
 70→	full := calculateTokenUsage(agent.AgentTypeClaudeCode, data, 0)
 71→	sliced := calculateTokenUsage(agent.AgentTypeClaudeCode, data, 2)
 72→
 73→	if full == nil || sliced == nil {
 74→		t.Fatal("expected non-nil results")
 75→	}
 76→	if full.OutputTokens != 20 {
 77→		t.Errorf("full OutputTokens = %d, want 20", full.OutputTokens)
 78→	}
 79→	if sliced.OutputTokens != 15 {
 80→		t.Errorf("sliced OutputTokens = %d, want 15", sliced.OutputTokens)
 81→	}
