168→func TestGenerateContextFromPrompts_CJKTruncation(t *testing.T) {
169→	t.Parallel()
170→
171→	// 600 CJK characters exceeds the 500-rune truncation limit.
172→	prompt := strings.Repeat("あ", 600)
173→
174→	result := generateContextFromPrompts([]string{prompt})
175→
176→	if !utf8.Valid(result) {
177→		t.Error("generateContextFromPrompts produced invalid UTF-8 when truncating a CJK prompt")
178→	}
179→
180→	resultStr := string(result)
181→	if !strings.Contains(resultStr, "...") {
182→		t.Error("expected truncated CJK prompt to contain '...' suffix")
183→	}
184→	// Should not contain more than 500 CJK characters
185→	if strings.Contains(resultStr, strings.Repeat("あ", 501)) {
186→		t.Error("CJK prompt was not truncated")
187→	}
188→}
