 19→// BenchmarkPostCommit measures the full PostCommit hook execution time.
 20→// This is the baseline before introducing a postCommitCache.
 21→//
 22→// Setup: 1 active session with a shadow branch checkpoint, then a commit
 23→// with the Entire-Checkpoint trailer. PostCommit reads HEAD, finds the session,
 24→// runs condensation (filesOverlapWithContent, CondenseSession, carry-forward).
 25→func BenchmarkPostCommit(b *testing.B) {
 26→	b.Run("SingleSession_Active", benchPostCommitSingleSession(session.PhaseActive))
 27→	b.Run("SingleSession_Idle", benchPostCommitSingleSession(session.PhaseIdle))
 28→	b.Run("MultipleSessions_2", benchPostCommitMultipleSessions(2))
 29→	b.Run("MultipleSessions_3", benchPostCommitMultipleSessions(3))
 30→}
 31→
 32→func benchPostCommitSingleSession(phase session.Phase) func(*testing.B) {
 33→	return func(b *testing.B) {
 34→		for range b.N {
 35→			b.StopTimer()
 36→			dir := benchSetupPostCommitRepo(b, phase, 1)
 37→			b.Chdir(dir)
 38→			paths.ClearWorktreeRootCache()
 39→			b.StartTimer()
 40→
 41→			s := &ManualCommitStrategy{}
 42→			if err := s.PostCommit(); err != nil {
 43→				b.Fatalf("PostCommit: %v", err)
 44→			}
 45→		}
 46→	}
 47→}
 48→
 49→func benchPostCommitMultipleSessions(sessionCount int) func(*testing.B) {
 50→	return func(b *testing.B) {
 51→		for range b.N {
 52→			b.StopTimer()
 53→			dir := benchSetupPostCommitRepo(b, session.PhaseActive, sessionCount)
 54→			b.Chdir(dir)
 55→			paths.ClearWorktreeRootCache()
 56→			b.StartTimer()
 57→
 58→			s := &ManualCommitStrategy{}
 59→			if err := s.PostCommit(); err != nil {
 60→				b.Fatalf("PostCommit: %v", err)
 61→			}
 62→		}
 63→	}
 64→}
