 66→// benchSetupPostCommitRepo creates a git repo with N sessions that have shadow branch
 67→// checkpoints, then creates a commit with the Entire-Checkpoint trailer.
 68→// Returns the repo directory path, ready for PostCommit() to run.
 69→func benchSetupPostCommitRepo(b *testing.B, phase session.Phase, sessionCount int) string {
 70→	b.Helper()
 71→
 72→	dir := b.TempDir()
 73→	// Resolve symlinks (macOS /var -> /private/var)
 74→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
 75→		dir = resolved
 76→	}
 77→
 78→	repo, err := git.PlainInit(dir, false)
 79→	if err != nil {
 80→		b.Fatalf("git init: %v", err)
 81→	}
 82→
 83→	// Configure git user
 84→	cfg, err := repo.Config()
 85→	if err != nil {
 86→		b.Fatalf("config: %v", err)
 87→	}
 88→	cfg.User.Name = "Bench User"
 89→	cfg.User.Email = "bench@example.com"
 90→	if err := repo.SetConfig(cfg); err != nil {
 91→		b.Fatalf("set config: %v", err)
 92→	}
 93→
 94→	// Create initial files and commit
 95→	wt, err := repo.Worktree()
 96→	if err != nil {
 97→		b.Fatalf("worktree: %v", err)
 98→	}
 99→
100→	// Create multiple files to make file overlap checks realistic
101→	for i := range 5 {
102→		name := fmt.Sprintf("src/file_%d.go", i)
103→		abs := filepath.Join(dir, name)
104→		if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
105→			b.Fatalf("mkdir: %v", err)
106→		}
107→		content := fmt.Sprintf("package main\nfunc f%d() {}\n", i)
108→		if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
109→			b.Fatalf("write: %v", err)
110→		}
111→		if _, err := wt.Add(name); err != nil {
112→			b.Fatalf("add: %v", err)
113→		}
114→	}
115→
116→	if _, err := wt.Commit("initial commit", &git.CommitOptions{
117→		Author: &object.Signature{Name: "Bench", Email: "bench@test.com", When: time.Now()},
118→	}); err != nil {
119→		b.Fatalf("commit: %v", err)
120→	}
121→
122→	s := &ManualCommitStrategy{}
123→
124→	// Chdir to repo dir for the entire setup (SaveStep, loadSessionState, etc.
125→	// all depend on paths.WorktreeRoot() which uses cwd). b.Chdir restores
126→	// the original directory when the benchmark function returns.
127→	b.Chdir(dir)
128→	paths.ClearWorktreeRootCache()
129→
130→	// Set up each session with a shadow branch checkpoint
131→	modifiedFiles := []string{"src/file_0.go", "src/file_1.go"}
132→	for i := range sessionCount {
133→		sessionID := fmt.Sprintf("bench-session-%d", i)
134→
135→		// Modify files with agent content
136→		for _, f := range modifiedFiles {
137→			abs := filepath.Join(dir, f)
138→			content := fmt.Sprintf("package main\n// modified by agent session %d\nfunc f() {}\n", i)
139→			if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
140→				b.Fatalf("write: %v", err)
141→			}
142→		}
143→
144→		// Create metadata directory with transcript
145→		metadataDir := ".entire/metadata/" + sessionID
146→		metadataDirAbs := filepath.Join(dir, metadataDir)
147→		if err := os.MkdirAll(metadataDirAbs, 0o755); err != nil {
148→			b.Fatalf("mkdir: %v", err)
149→		}
150→		transcript := `{"type":"human","message":{"content":"implement feature"}}
151→{"type":"assistant","message":{"content":"I'll implement that for you."}}
152→`
153→		if err := os.WriteFile(filepath.Join(metadataDirAbs, paths.TranscriptFileName), []byte(transcript), 0o644); err != nil {
154→			b.Fatalf("write transcript: %v", err)
155→		}
156→
157→		paths.ClearWorktreeRootCache()
158→
159→		if err := s.SaveStep(StepContext{
160→			SessionID:      sessionID,
161→			ModifiedFiles:  modifiedFiles,
162→			NewFiles:       []string{},
163→			DeletedFiles:   []string{},
164→			MetadataDir:    metadataDir,
165→			MetadataDirAbs: metadataDirAbs,
166→			CommitMessage:  "Checkpoint 1",
167→			AuthorName:     "Bench",
168→			AuthorEmail:    "bench@test.com",
169→		}); err != nil {
170→			b.Fatalf("SaveStep: %v", err)
171→		}
172→
173→		// Set the session phase
174→		state, err := s.loadSessionState(sessionID)
175→		if err != nil {
176→			b.Fatalf("load state: %v", err)
177→		}
178→		state.Phase = phase
179→		state.FilesTouched = modifiedFiles
180→		if err := s.saveSessionState(state); err != nil {
181→			b.Fatalf("save state: %v", err)
182→		}
183→	}
184→
185→	// Create the user commit with checkpoint trailer (the commit PostCommit will process)
186→	cpID, err := id.Generate()
187→	if err != nil {
188→		b.Fatalf("generate ID: %v", err)
189→	}
190→
191→	// Modify a file and commit with trailer
192→	testFile := filepath.Join(dir, "src/file_0.go")
193→	if err := os.WriteFile(testFile, []byte("package main\n// modified by agent session 0\nfunc f() {}\n"), 0o644); err != nil {
194→		b.Fatalf("write: %v", err)
195→	}
196→	if _, err := wt.Add("src/file_0.go"); err != nil {
197→		b.Fatalf("add: %v", err)
198→	}
199→
200→	commitMsg := fmt.Sprintf("implement feature\n\n%s: %s\n", trailers.CheckpointTrailerKey, cpID)
201→	if _, err := wt.Commit(commitMsg, &git.CommitOptions{
202→		Author: &object.Signature{Name: "Bench", Email: "bench@test.com", When: time.Now()},
203→	}); err != nil {
204→		b.Fatalf("commit: %v", err)
205→	}
206→
207→	return dir
208→}
